export function runAbRegressionDiff(scenarioId = "hybrid-rrf-upgrade", options = {}) {
  const t0 = performance.now();
  const scenario = AB_DIFF_SCENARIOS[scenarioId] ?? AB_DIFF_SCENARIOS["hybrid-rrf-upgrade"];
  const topK = options.topK ?? scenario.topK ?? 2;
  const maxFaithfulnessDrop = options.maxFaithfulnessDrop ?? 0.01;
  const maxContextPrecisionDrop = options.maxContextPrecisionDrop ?? 0.02;
  const maxRecallDrop = options.maxRecallDrop ?? 0.01;
  const maxCaseRegressions = options.maxCaseRegressions ?? 0;
  const caseEpsilon = options.caseEpsilon ?? 0.005;

  const baseScored = scenario.baseline.map((c) => evaluateGoldenCase(c, topK));
  const candScored = scenario.candidate.map((c) => evaluateGoldenCase(c, topK));
  const avgMetric = (arr, key) =>
    Number((arr.reduce((acc, x) => acc + x[key], 0) / Math.max(1, arr.length)).toFixed(4));

  const baselineSummary = {
    totalCases: baseScored.length,
    faithfulness: avgMetric(baseScored, "faithfulness"),
    contextPrecision: avgMetric(baseScored, "contextPrecision"),
    recallAtK: avgMetric(baseScored, "recallAtK")
  };
  const candidateSummary = {
    totalCases: candScored.length,
    faithfulness: avgMetric(candScored, "faithfulness"),
    contextPrecision: avgMetric(candScored, "contextPrecision"),
    recallAtK: avgMetric(candScored, "recallAtK")
  };

  const candById = new Map(candScored.map((c) => [c.id, c]));
  const rawBaseById = new Map(scenario.baseline.map((c) => [c.id, c]));
  const rawCandById = new Map(scenario.candidate.map((c) => [c.id, c]));

  const caseDiffs = [];
  const compositeDeltas = [];
  const jaccards = [];
  const wordDeltas = [];
  const answerCosines = [];

  for (const bCase of baseScored) {
    const cCase = candById.get(bCase.id);
    if (!cCase) continue;

    const dFaith = Number((cCase.faithfulness - bCase.faithfulness).toFixed(4));
    const dPrec = Number((cCase.contextPrecision - bCase.contextPrecision).toFixed(4));
    const dRec = Number((cCase.recallAtK - bCase.recallAtK).toFixed(4));
    const bComp = (bCase.faithfulness + bCase.contextPrecision + bCase.recallAtK) / 3.0;
    const cComp = (cCase.faithfulness + cCase.contextPrecision + cCase.recallAtK) / 3.0;
    const compositeDelta = Number((cComp - bComp).toFixed(4));
    compositeDeltas.push(compositeDelta);

    const reasons = [];
    if (dFaith < -caseEpsilon) reasons.push("faithfulness_drop");
    if (dPrec < -caseEpsilon) reasons.push("precision_rank_drop");
    if (dRec < -caseEpsilon) reasons.push("recall_chunk_miss");

    let status = "unchanged";
    if (compositeDelta < -caseEpsilon || reasons.length > 0) {
      status = "regressed";
    } else if (compositeDelta > caseEpsilon) {
      status = "improved";
    }

    const rawB = rawBaseById.get(bCase.id);
    const rawC = rawCandById.get(bCase.id);
    const jacc = Number(chunkIdJaccard(rawB.retrievedDocs, rawC.retrievedDocs, topK).toFixed(4));
    const wDelta = Number(
      (meanChunkWords(rawC.retrievedDocs, topK) - meanChunkWords(rawB.retrievedDocs, topK)).toFixed(2)
    );
    const ansSim = Number(
      Math.max(0, cosine(embed256(rawB.generatedAnswer), embed256(rawC.generatedAnswer))).toFixed(4)
    );

    jaccards.push(jacc);
    wordDeltas.push(wDelta);
    answerCosines.push(ansSim);

    caseDiffs.push({
      id: bCase.id,
      status,
      compositeDelta,
      faithfulnessDelta: dFaith,
      contextPrecisionDelta: dPrec,
      recallAtKDelta: dRec,
      reasons,
      chunkOverlapJaccard: jacc,
      chunkWordsDelta: wDelta,
      answerCosineSimilarity: ansSim
    });
  }

  const regressions = caseDiffs.filter((c) => c.status === "regressed");
  const improvements = caseDiffs.filter((c) => c.status === "improved");
  const unchanged = caseDiffs.length - regressions.length - improvements.length;

  const deltas = {
    faithfulness: Number((candidateSummary.faithfulness - baselineSummary.faithfulness).toFixed(4)),
    contextPrecision: Number((candidateSummary.contextPrecision - baselineSummary.contextPrecision).toFixed(4)),
    recallAtK: Number((candidateSummary.recallAtK - baselineSummary.recallAtK).toFixed(4))
  };

  const meanArr = (arr, digits = 4) =>
    Number((arr.reduce((s, v) => s + v, 0) / Math.max(1, arr.length)).toFixed(digits));

  const drift = {
    meanChunkOverlapJaccard: meanArr(jaccards, 4),
    meanChunkWordsDelta: meanArr(wordDeltas, 2),
    meanAnswerCosineSimilarity: meanArr(answerCosines, 4),
    pairedStats: computePairedStats(compositeDeltas)
  };

  const gateFailures = [];
  if (deltas.faithfulness < -maxFaithfulnessDrop) {
    gateFailures.push(
      `Faithfulness delta ${deltas.faithfulness.toFixed(4)} < -${maxFaithfulnessDrop.toFixed(4)}`
    );
  }
  if (deltas.contextPrecision < -maxContextPrecisionDrop) {
    gateFailures.push(
      `AP@${topK} delta ${deltas.contextPrecision.toFixed(4)} < -${maxContextPrecisionDrop.toFixed(4)}`
    );
  }
  if (deltas.recallAtK < -maxRecallDrop) {
    gateFailures.push(
      `Recall@${topK} delta ${deltas.recallAtK.toFixed(4)} < -${maxRecallDrop.toFixed(4)}`
    );
  }
  if (regressions.length > maxCaseRegressions) {
    gateFailures.push(
      `Regressed cases (${regressions.length}) > maxCaseRegressions (${maxCaseRegressions})`
    );
  }

  return {
    scenarioId: scenario.id,
    label: scenario.label,
    summary: scenario.summary,
    topK,
    passed: gateFailures.length === 0,
    verdict: gateFailures.length === 0 ? "PASS" : "REGRESSION_DETECTED",
    gateFailures,
    matchedCases: caseDiffs.length,
    baseline: baselineSummary,
    candidate: candidateSummary,
    deltas,
    drift,
    caseBreakdown: {
      improved: improvements.length,
      regressed: regressions.length,
      unchanged
    },
    caseDiffs,
    elapsedMs: Number((performance.now() - t0).toFixed(3))
  };
}

// ============================================================================
// Increment v1.1 Part B: Rust wasm32-unknown-unknown P² Quantile & CRC32C Engine
// Mirrors `polyglot-agent-runtime-rs` v1.1.0 (`512 B` wasm32 O(1) state)
// ============================================================================

export function crc32cPortable(bytes) {
  if (!bytes || bytes.length === 0) return 0;
  let crc = 0xffffffff;
  for (let i = 0; i < bytes.length; i += 1) {
    crc ^= bytes[i];
    for (let bit = 0; bit < 8; bit += 1) {
      const mask = -(crc & 1);
      crc = (crc >>> 1) ^ (0x82f63b78 & mask);
    }
  }
  return (~crc) >>> 0;
}

export class P2QuantileJs {
  constructor(p) {
    this.p = p;
    this.count = 0;
    this.q = new Float64Array(5);
    this.n = [1, 2, 3, 4, 5];
    this.np = [1.0, 1.0 + 2.0 * p, 1.0 + 4.0 * p, 3.0 + 2.0 * p, 5.0];
    this.dn = [0.0, p / 2.0, p, (1.0 + p) / 2.0, 1.0];
  }

  observe(x) {
    if (!Number.isFinite(x)) return;
    if (this.count < 5) {
      this.q[this.count] = x;
      this.count += 1;
      if (this.count === 5) {
        for (let i = 1; i < 5; i += 1) {
          const key = this.q[i];
          let j = i;
          while (j > 0 && this.q[j - 1] > key) {
            this.q[j] = this.q[j - 1];
            j -= 1;
          }
          this.q[j] = key;
        }
      }
      return;
    }

    this.count += 1;
    let k = 0;
    if (x < this.q[0]) {
      this.q[0] = x;
      k = 0;
    } else if (x < this.q[1]) {
      k = 0;
    } else if (x < this.q[2]) {
      k = 1;
    } else if (x < this.q[3]) {
      k = 2;
    } else if (x <= this.q[4]) {
      k = 3;
    } else {
      this.q[4] = x;
      k = 3;
    }

    for (let pos = k + 1; pos < 5; pos += 1) {
      this.n[pos] += 1;
    }
    for (let m = 0; m < 5; m += 1) {
      this.np[m] += this.dn[m];
    }

    for (let i = 1; i <= 3; i += 1) {
      const d = this.np[i] - this.n[i];
      if ((d >= 1.0 && this.n[i + 1] - this.n[i] > 1) || (d <= -1.0 && this.n[i - 1] - this.n[i] < -1)) {
        const dSign = d >= 0.0 ? 1 : -1;
        const nI = this.n[i];
        const nIm1 = this.n[i - 1];
        const nIp1 = this.n[i + 1];

        const term1 = ((nI - nIm1 + dSign) * (this.q[i + 1] - this.q[i])) / (nIp1 - nI);
        const term2 = ((nIp1 - nI - dSign) * (this.q[i] - this.q[i - 1])) / (nI - nIm1);
        const qp = this.q[i] + (dSign / (nIp1 - nIm1)) * (term1 + term2);

        if (this.q[i - 1] < qp && qp < this.q[i + 1]) {
          this.q[i] = qp;
        } else {
          const adj = i + dSign;
          this.q[i] += (dSign * (this.q[adj] - this.q[i])) / (this.n[adj] - nI);
        }
        this.n[i] += dSign;
      }
    }
  }

  estimate() {
    if (this.count === 0) return 0.0;
    if (this.count <= 4) {
      const tmp = Array.from(this.q.slice(0, this.count)).sort((a, b) => a - b);
      const rank = this.p * (tmp.length - 1);
      const lo = Math.floor(rank);
      const hi = Math.ceil(rank);
      return lo === hi ? tmp[lo] : tmp[lo] + (rank - lo) * (tmp[hi] - tmp[lo]);
    }
    return this.q[2];
  }
}

export class StreamingQuantileSuiteJs {
  constructor() {
    this.p50 = new P2QuantileJs(0.5);
    this.p95 = new P2QuantileJs(0.95);
    this.p99 = new P2QuantileJs(0.99);
    this.count = 0;
    this.mean = 0.0;
    this.min = Infinity;
    this.max = -Infinity;
  }

  observeBatch(samples) {
    for (let i = 0; i < samples.length; i += 1) {
      const x = samples[i];
      if (!Number.isFinite(x)) continue;
      this.count += 1;
      this.mean += (x - this.mean) / this.count;
      if (x < this.min) this.min = x;
      if (x > this.max) this.max = x;
      this.p50.observe(x);
      this.p95.observe(x);
      this.p99.observe(x);
    }
    return this.count;
  }

  snapshot() {
    if (this.count === 0) {
      return { count: 0, min: 0, p50: 0, p95: 0, p99: 0, max: 0, mean: 0, stateBytes: 512 };
    }
    return {
      count: this.count,
      min: this.min,
      p50: this.p50.estimate(),
      p95: this.p95.estimate(),
      p99: this.p99.estimate(),
      max: this.max,
      mean: this.mean,
      stateBytes: 512
    };
  }
}

let cachedWasmExports = null;

export async function instantiateWasmRuntime(wasmSource = null) {
  if (wasmSource === null && cachedWasmExports) {
    return cachedWasmExports;
  }
  let bytes = wasmSource;
  if (!bytes) {
    try {
      const wasmUrl = new URL("./assets/polyglot_agent_runtime.wasm", import.meta.url);
      const resp = await fetch(wasmUrl);
      if (resp.ok) {
        bytes = await resp.arrayBuffer();
      } else {
        bytes = decodeEmbeddedWasmBytes();
      }
    } catch {
      bytes = decodeEmbeddedWasmBytes();
    }
  }
  const { instance } = await WebAssembly.instantiate(bytes, {});
  if (wasmSource === null) {
    cachedWasmExports = instance.exports;
  }
  return instance.exports;
}

export function generateLatencyStream(distribution = "bimodal-kv-cache", sampleCount = 40000, tailSpikePct = 4) {
  const n = Math.max(100, Math.min(200000, Math.trunc(sampleCount)));
  const spikeRate = Math.max(0, Math.min(25, Number(tailSpikePct))) / 100.0;
  const out = new Float64Array(n);
  let seed = 0x9e3779b9;
  const nextRand = () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296.0;
  };

  for (let i = 0; i < n; i += 1) {
    if (distribution === "weyl-uniform") {
      const base = ((i * 0.6180339887498949) % 1.0) * 1000.0;
      const u = nextRand();
      out[i] = u < spikeRate ? base + 350.0 + u * 600.0 : base;
      continue;
    }
    const u1 = Math.max(1e-7, nextRand());
    const u2 = nextRand();
    const z0 = Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2.0 * Math.PI * u2);

    if (distribution === "lognormal-rpc") {
      let sample = Math.exp(2.65 + 0.42 * z0);
      if (nextRand() < spikeRate) sample += 140.0 + Math.abs(z0) * 65.0;
      out[i] = sample;
    } else if (distribution === "pareto-moe-burst") {
      const pareto = 12.0 / Math.pow(1.0 - Math.min(0.995, u2), 1.0 / 2.35);
      out[i] = nextRand() < spikeRate ? pareto + 210.0 : pareto;
    } else {
      // bimodal-kv-cache: warm slot hit (~2.6 ms) vs cold MoE prefill (~78 ms) + tail spike
      const hit = nextRand() >= 0.18;
      let sample = hit ? Math.max(0.4, 2.6 + 0.55 * z0) : Math.max(18.0, 78.0 + 14.0 * z0);
      if (nextRand() < spikeRate) sample += 185.0 + Math.abs(z0) * 48.0;
      out[i] = sample;
    }
  }
  return out;
}

function exactSortedQuantile(sorted, p) {
  if (sorted.length === 0) return 0.0;
  const rank = p * (sorted.length - 1);
  const lo = Math.floor(rank);
  const hi = Math.ceil(rank);
  return lo === hi ? sorted[lo] : sorted[lo] + (rank - lo) * (sorted[hi] - sorted[lo]);
}

export function runP2QuantileExplorer(options = {}) {
  const distribution = options.distribution ?? "bimodal-kv-cache";
  const sampleCount = options.sampleCount ?? 40000;
  const tailSpikePct = options.tailSpikePct ?? 4;
  const ex = options.wasmExports !== undefined ? options.wasmExports : cachedWasmExports;

  const samples = generateLatencyStream(distribution, sampleCount, tailSpikePct);
  let snap;
  let engine = "es2022-p2-fallback";
  let rfc3720Hex = "0xE3069283";
  let frameCrcHex = "0x00000000";
  let streamElapsedMs = 0;

  if (ex && typeof ex.par_p2_suite_new === "function") {
    engine = "wasm32-unknown-unknown";
    const stateBytes = ex.par_p2_suite_state_bytes();
    const suitePtr = ex.par_p2_suite_new();
    const bufPtr = ex.par_p2_alloc_f64_buffer(samples.length);
    new Float64Array(ex.memory.buffer, bufPtr, samples.length).set(samples);

    const t0 = performance.now();
    const count = Number(ex.par_p2_suite_observe_batch(suitePtr, bufPtr, samples.length));
    streamElapsedMs = Math.max(0.001, performance.now() - t0);

    snap = {
      count,
      min: ex.par_p2_suite_min(suitePtr),
      p50: ex.par_p2_suite_p50(suitePtr),
      p95: ex.par_p2_suite_p95(suitePtr),
      p99: ex.par_p2_suite_p99(suitePtr),
      max: ex.par_p2_suite_max(suitePtr),
      mean: ex.par_p2_suite_mean(suitePtr),
      stateBytes
    };

    ex.par_p2_free_f64_buffer(bufPtr, samples.length);
    ex.par_p2_suite_free(suitePtr);

    const enc = new TextEncoder();
    const checkBytes = enc.encode("123456789");
    const cPtr = ex.par_wasm_alloc_bytes(checkBytes.length);
    new Uint8Array(ex.memory.buffer, cPtr, checkBytes.length).set(checkBytes);
    rfc3720Hex = "0x" + (ex.par_wasm_crc32c(cPtr, checkBytes.length) >>> 0).toString(16).toUpperCase().padStart(8, "0");
    ex.par_wasm_free_bytes(cPtr, checkBytes.length);

    const frameBytes = enc.encode(
      `par1|${distribution}|n=${snap.count}|p50=${snap.p50.toFixed(3)}|p95=${snap.p95.toFixed(3)}|p99=${snap.p99.toFixed(3)}`
    );
    const fPtr = ex.par_wasm_alloc_bytes(frameBytes.length);
    new Uint8Array(ex.memory.buffer, fPtr, frameBytes.length).set(frameBytes);
    frameCrcHex = "0x" + (ex.par_wasm_crc32c(fPtr, frameBytes.length) >>> 0).toString(16).toUpperCase().padStart(8, "0");
    ex.par_wasm_free_bytes(fPtr, frameBytes.length);
  } else {
    const suite = new StreamingQuantileSuiteJs();
    const t0 = performance.now();
    suite.observeBatch(samples);
    streamElapsedMs = Math.max(0.001, performance.now() - t0);
    snap = suite.snapshot();

    const enc = new TextEncoder();
    rfc3720Hex = "0x" + crc32cPortable(enc.encode("123456789")).toString(16).toUpperCase().padStart(8, "0");
    const frameBytes = enc.encode(
      `par1|${distribution}|n=${snap.count}|p50=${snap.p50.toFixed(3)}|p95=${snap.p95.toFixed(3)}|p99=${snap.p99.toFixed(3)}`
    );
    frameCrcHex = "0x" + crc32cPortable(frameBytes).toString(16).toUpperCase().padStart(8, "0");
  }

  // Exact O(N) sorted reference comparison
  const sorted = Float64Array.from(samples).sort();
  const exactP50 = exactSortedQuantile(sorted, 0.5);
  const exactP95 = exactSortedQuantile(sorted, 0.95);
  const exactP99 = exactSortedQuantile(sorted, 0.99);

  const relErrPct = (est, exact) =>
    exact > 1e-9 ? Number(((Math.abs(est - exact) / exact) * 100.0).toFixed(2)) : 0.0;

  const naiveArrayBytes = samples.length * 8;
  const compressionRatio = Number((naiveArrayBytes / snap.stateBytes).toFixed(1));
  const obsPerSec = Number((samples.length / (streamElapsedMs / 1000.0)).toFixed(0));

  return {
    engine,
    distribution,
    count: snap.count,
    stateBytes: snap.stateBytes,
    naiveArrayBytes,
    compressionRatio,
    streamElapsedMs: Number(streamElapsedMs.toFixed(3)),
    obsPerSec,
    min: Number(snap.min.toFixed(2)),
    mean: Number(snap.mean.toFixed(2)),
    max: Number(snap.max.toFixed(2)),
    p50: Number(snap.p50.toFixed(2)),
    p95: Number(snap.p95.toFixed(2)),
    p99: Number(snap.p99.toFixed(2)),
    exact: {
      p50: Number(exactP50.toFixed(2)),
      p95: Number(exactP95.toFixed(2)),
      p99: Number(exactP99.toFixed(2))
    },
    relErrorPct: {
      p50: relErrPct(snap.p50, exactP50),
      p95: relErrPct(snap.p95, exactP95),
      p99: relErrPct(snap.p99, exactP99)
    },
    rfc3720Crc32cHex: rfc3720Hex,
    frameCrc32cHex: frameCrcHex
  };
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function fmtSigned(num, digits = 4) {
  const fixed = Number(num).toFixed(digits);
  return num >= 0 ? `+${fixed}` : fixed;
}

// ============================================================================
// Increment v1.2 Part A: MCP 2025-11-25 Capability Negotiation & FTS5 Citation Spans
// Mirrors `mcp-moe-hybrid-sdk` v1.2.0 (`d4b1a33`)
// ============================================================================

export const SUPPORTED_MCP_VERSIONS = Object.freeze([
  "2025-11-25",
  "2025-06-18",
  "2025-03-26",
  "2024-11-05"
]);

export function negotiateMcpCapabilities(requestedVersion = "2025-11-25") {
  const reqVer = String(requestedVersion || "2025-11-25").trim();
  const supported = SUPPORTED_MCP_VERSIONS.includes(reqVer);
  const negotiatedVersion = supported ? reqVer : "2025-11-25";

  const resources = [
    {
      uri: "mcp://moe-router/tiers",
      name: "Sparse Top-2 MoE Tier Table & SLA Telemetry",
      mimeType: "application/json"
    },
    {
      uri: "mcp://telemetry/otlp",
      name: "OpenTelemetry (OTLP/JSON) Spans & Histograms",
      mimeType: "application/json"
    },
    ...CORPUS.map((doc) => ({
      uri: `vault://documents/${doc.id}`,
      name: doc.title,
      mimeType: "application/json"
    }))
  ];

  const resourceTemplates = [
    {
      uriTemplate: "vault://documents/{doc_id}",
      name: "Hybrid Knowledge Vault Document",
      mimeType: "application/json"
    }
  ];

  const prompts = [
    {
      name: "grounded_rag_answer",
      requiredArgs: ["query"],
      optionalArgs: ["top_k"]
    },
    {
      name: "moe_sla_routing_plan",
      requiredArgs: ["task"],
      optionalArgs: ["max_vram_gib", "latency_sla_ms"]
    }
  ];

  return {
    requestedVersion: reqVer,
    negotiatedVersion,
    fallbackApplied: !supported,
    capabilities: {
      tools: { listChanged: false },
      resources: { subscribe: false, listChanged: false },
      prompts: { listChanged: false }
    },
    resourcesCount: resources.length,
    resources,
    resourceTemplates,
    prompts
  };
}

export function extractCitationSpans(plainText, queryTokens, field = "body") {
  const text = String(plainText ?? "");
  const lower = text.toLowerCase();
  const uniqTerms = [...new Set((queryTokens ?? []).map((t) => String(t).toLowerCase()).filter((t) => t.length >= 2))]
    .sort((a, b) => b.length - a.length);

  const rawRanges = [];
  for (const term of uniqTerms) {
    let fromIdx = 0;
    while (fromIdx < lower.length) {
      const idx = lower.indexOf(term, fromIdx);
      if (idx === -1) break;
      const beforeOk = idx === 0 || !/[a-z0-9]/.test(lower[idx - 1]);
      const end = idx + term.length;
      if (beforeOk) {
        rawRanges.push({ start: idx, end });
      }
      fromIdx = idx + 1;
    }
  }

  rawRanges.sort((a, b) => a.start - b.start || b.end - a.end);
  const merged = [];
  for (const r of rawRanges) {
    const prev = merged[merged.length - 1];
    if (!prev || r.start >= prev.end) {
      merged.push({ start: r.start, end: r.end });
    } else if (r.end > prev.end) {
      prev.end = r.end;
    }
  }

  const spans = merged.map((r) => ({
    field,
    term: text.slice(r.start, r.end),
    start: r.start,
    end: r.end
  }));

  let cursor = 0;
  let htmlOut = "";
  for (const sp of spans) {
    htmlOut += escapeHtml(text.slice(cursor, sp.start));
    htmlOut += `<mark>${escapeHtml(text.slice(sp.start, sp.end))}</mark>`;
    cursor = sp.end;
  }
  htmlOut += escapeHtml(text.slice(cursor));

  return { spans, highlightedHtml: htmlOut };
}

export function inspectMcpCitationSpans(rawQuery, options = {}) {
  const t0 = performance.now();
  const topK = Math.max(1, Math.min(6, options.topK ?? 3));
  const requestedVersion = options.requestedVersion ?? "2025-11-25";
  const { cleanQuery, redactions } = redactQuery(rawQuery);
  const qTokens = tokenize(cleanQuery);
  const mcp = negotiateMcpCapabilities(requestedVersion);
  const baseHits = searchHybridRrf(cleanQuery, topK, 60);

  let totalSpans = 0;
  const hits = baseHits.map((hit) => {
    const titleRes = extractCitationSpans(hit.title, qTokens, "title");
    const bodyRes = extractCitationSpans(hit.body, qTokens, "body");
    const citationSpans = [...titleRes.spans, ...bodyRes.spans];
    totalSpans += citationSpans.length;
    return {
      ...hit,
      resourceUri: `vault://documents/${hit.id}`,
      highlightedTitleHtml: titleRes.highlightedHtml,
      highlightedBodyHtml: bodyRes.highlightedHtml,
      citationSpans
    };
  });

  const groundedPrompt = [
    "Answer the query strictly from the cited evidence passages and cite [doc_id] inline.",
    `Query: ${cleanQuery}`,
    ...hits.map((h) => `[${h.id}] (rrf=${h.rrf.toFixed(4)}, spans=${h.citationSpans.length}): ${h.title}`)
  ].join("\n");

  return {
    cleanQuery,
    redactions,
    mcp,
    hits,
    totalSpans,
    groundedPrompt,
    elapsedMs: Number((performance.now() - t0).toFixed(3))
  };
}

// ============================================================================
// Increment v1.2 Part B: C11/WASM 64B Rational Token-Bucket, 256B Audit Ring
// & W3C `traceparent` + OTLP/JSON Trace Waterfall Inspector
// Mirrors `polyglot-agent-runtime-rs` v1.2.0 & `fullstack-rag-eval-studio` v1.2.0
// ============================================================================

const W3C_TRACEPARENT_RE = /^00-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$/i;
const OTLP_BOUNDS_MS = Object.freeze([0.1, 0.25, 0.5, 1, 2.5, 5, 10, 25, 50, 100, 250]);

export function parseW3cTraceparent(rawHeader) {
  if (typeof rawHeader !== "string") return null;
  const m = W3C_TRACEPARENT_RE.exec(rawHeader.trim());
  if (!m) return null;
  const traceId = m[1].toLowerCase();
  const parentSpanId = m[2].toLowerCase();
  const traceFlags = m[3].toLowerCase();
  if (/^0+$/.test(traceId) || /^0+$/.test(parentSpanId)) return null;
  return { version: "00", traceId, parentSpanId, traceFlags };
}

function deterministicHex(seedText, hexChars) {
  let h1 = 0x811c9dc5;
  let h2 = 0x9e3779b9;
  const s = String(seedText);
  for (let i = 0; i < s.length; i += 1) {
    const c = s.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 0x01000193) >>> 0;
    h2 = Math.imul(h2 ^ (c + i), 0x85ebca6b) >>> 0;
  }
  let out = "";
  let state = (h1 ^ h2) >>> 0;
  while (out.length < hexChars) {
    state = (Math.imul(state ^ (state >>> 15), 0x2c1b3c6d) + 0x6d2b79f5) >>> 0;
    out += state.toString(16).padStart(8, "0");
  }
  const sliced = out.slice(0, hexChars);
  return /^0+$/.test(sliced) ? "1".padStart(hexChars, "0") : sliced;
}

class RationalTokenBucketJs {
  constructor(capacityMilli, refillPerSecMilli, initialNs) {
    this.capacity = BigInt(capacityMilli);
    this.tokens = BigInt(capacityMilli);
    this.refill = BigInt(refillPerSecMilli);
    this.lastNs = BigInt(initialNs);
    this.remNsNum = 0n;
    this.allowed = 0;
    this.denied = 0;
  }

  retryAfterNs(costMilli) {
    const cost = BigInt(costMilli);
    if (cost > this.capacity) return -1n;
    if (this.tokens >= cost) return 0n;
    if (this.refill === 0n) return -1n;
    const deficit = cost - this.tokens;
    const num = deficit * 1_000_000_000n - this.remNsNum;
    return (num + this.refill - 1n) / this.refill;
  }

  tryAcquire(costMilli, nowNs) {
    const cost = BigInt(costMilli);
    const now = BigInt(nowNs);
    if (this.capacity === 0n || cost > this.capacity) return -9;
    if (now > this.lastNs) {
      const elapsed = now - this.lastNs;
      this.lastNs = now;
      if (this.refill > 0n && this.tokens < this.capacity) {
        const headroom = this.capacity - this.tokens;
        const totalNum = elapsed * this.refill + this.remNsNum;
        const addMilli = totalNum / 1_000_000_000n;
        const newRem = totalNum % 1_000_000_000n;
        if (addMilli >= headroom) {
          this.tokens = this.capacity;
          this.remNsNum = 0n;
        } else {
          this.tokens += addMilli;
          this.remNsNum = newRem;
        }
      } else if (this.tokens >= this.capacity) {
        this.tokens = this.capacity;
        this.remNsNum = 0n;
      }
    }
    if (this.tokens >= cost) {
      this.tokens -= cost;
      this.allowed += 1;
      return 1;
    }
    this.denied += 1;
    return 0;
  }
}

export function runTokenBucketAndOtlpInspector(options = {}) {
  const capacityMilli = Math.max(1000, Math.trunc(options.capacityMilli ?? 5000));
  const refillPerSecMilli = Math.max(100, Math.trunc(options.refillPerSecMilli ?? 3333));
  const burstRequests = Math.max(1, Math.min(32, Math.trunc(options.burstRequests ?? 8)));
  const costPerReqMilli = Math.max(250, Math.trunc(options.costPerReqMilli ?? 1500));
  const stepMs = Math.max(10, Math.trunc(options.stepMs ?? 120));
  const injectTamperBitFlip = Boolean(options.injectTamperBitFlip);
  const rawQuery = options.query ?? "Castagnoli CRC32C 64-byte cache-line SQLite FTS5 Reciprocal Rank Fusion";
  const requestedVersion = options.requestedVersion ?? "2025-11-25";
  const inboundTraceparent = options.traceparent ?? "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01";
  const ex = options.wasmExports !== undefined ? options.wasmExports : cachedWasmExports;

  const parsedTp = parseW3cTraceparent(inboundTraceparent);
  const traceId = parsedTp ? parsedTp.traceId : deterministicHex(rawQuery, 32);
  const parentSpanId = parsedTp ? parsedTp.parentSpanId : "";
  const traceFlags = parsedTp ? parsedTp.traceFlags : "01";
  const rootSpanId = deterministicHex(`${traceId}:root:${burstRequests}:${capacityMilli}`, 16);
  const propagatedTraceparent = `00-${traceId}-${rootSpanId}-${traceFlags}`;

  let engine = "es2022-bigint-mirror";
  let bucketStateBytes = 64;
  let auditSlotBytes = 256;
  let allowedCount = 0;
  let deniedCount = 0;
  let remainingMilli = 0;
  let nextRetryAfterNs = 0;
  let primeConservationMilli = 0;
  let auditVerifiedSlots = 0;
  let auditVerifyCode = 0;
  const decisions = [];

  const hasWasmV12 =
    ex &&
    typeof ex.par_bucket_new === "function" &&
    typeof ex.par_audit_ring_new === "function";

  if (hasWasmV12) {
    engine = "wasm32-unknown-unknown";
    bucketStateBytes = ex.par_bucket_state_bytes();
    auditSlotBytes = ex.par_audit_ring_slot_bytes();

    // 1) Simulate burst traffic across 64-byte cache-line-aligned WASM ParTokenBucket
    const bPtr = ex.par_bucket_new(BigInt(capacityMilli), BigInt(refillPerSecMilli), 1_000_000n);
    const rPtr = ex.par_audit_ring_new();
    const enc = new TextEncoder();
    const msgBytes = enc.encode("mcp.tool:rag_hybrid_search");
    const msgPtr = ex.par_wasm_alloc_bytes(msgBytes.length);
    new Uint8Array(ex.memory.buffer, msgPtr, msgBytes.length).set(msgBytes);

    let nowNs = 1_000_000n;
    for (let i = 0; i < burstRequests; i += 1) {
      const rc = ex.par_bucket_try_acquire(bPtr, BigInt(costPerReqMilli), nowNs);
      const allowed = rc === 1;
      const waitNs = allowed ? 0 : Number(ex.par_bucket_retry_after_ns(bPtr, BigInt(costPerReqMilli)));
      const rem = Number(ex.par_bucket_tokens_milli(bPtr));
      // Record capability check into 256B/slot CRC32C audit ring (last slot tests GPU_DISPATCH deny if >4)
      const reqCaps = i === burstRequests - 1 && burstRequests >= 4 ? 0x10 : 0x09;
      ex.par_audit_ring_record(rPtr, nowNs, 7, reqCaps, 0x0f, msgPtr, msgBytes.length);
      decisions.push({
        reqIndex: i + 1,
        atMs: Number((nowNs - 1_000_000n) / 1_000_000n),
        allowed,
        remainingMilli: rem,
        retryAfterMs: Number((waitNs / 1_000_000).toFixed(3))
      });
      nowNs += BigInt(stepMs) * 1_000_000n;
    }

    allowedCount = Number(ex.par_bucket_allowed_count(bPtr));
    deniedCount = Number(ex.par_bucket_denied_count(bPtr));
    remainingMilli = Number(ex.par_bucket_tokens_milli(bPtr));
    nextRetryAfterNs = Number(ex.par_bucket_retry_after_ns(bPtr, BigInt(costPerReqMilli)));

    if (injectTamperBitFlip && ex.par_audit_ring_len(rPtr) > 0) {
      const slot0Ptr = ex.par_audit_ring_slot_ptr(rPtr, 0);
      new Uint8Array(ex.memory.buffer, slot0Ptr + 64, 1)[0] ^= 0x01;
    }
    auditVerifyCode = ex.par_audit_ring_verify_all(rPtr);
    auditVerifiedSlots = auditVerifyCode >= 0 ? auditVerifyCode : 0;

    ex.par_wasm_free_bytes(msgPtr, msgBytes.length);
    ex.par_audit_ring_free(rPtr);
    ex.par_bucket_free(bPtr);

    // 2) Verify exact 1,000 x 1ms sub-nanosecond conservation at refillPerSecMilli (zero float drift)
    const pPtr = ex.par_bucket_new(BigInt(Math.max(capacityMilli, refillPerSecMilli + 1000)), BigInt(refillPerSecMilli), 1_000_000n);
    const fullCap = BigInt(Math.max(capacityMilli, refillPerSecMilli + 1000));
    ex.par_bucket_try_acquire(pPtr, fullCap, 1_000_000n);
    let tNs = 1_000_000n;
    for (let s = 0; s < 1000; s += 1) {
      tNs += 1_000_000n;
      ex.par_bucket_try_acquire(pPtr, fullCap, tNs);
    }
    primeConservationMilli = Number(ex.par_bucket_tokens_milli(pPtr));
    ex.par_bucket_free(pPtr);
  } else {
    const tb = new RationalTokenBucketJs(capacityMilli, refillPerSecMilli, 1_000_000n);
    let nowNs = 1_000_000n;
    for (let i = 0; i < burstRequests; i += 1) {
      const rc = tb.tryAcquire(costPerReqMilli, nowNs);
      const allowed = rc === 1;
      const waitNs = allowed ? 0 : Number(tb.retryAfterNs(costPerReqMilli));
      decisions.push({
        reqIndex: i + 1,
        atMs: Number((nowNs - 1_000_000n) / 1_000_000n),
        allowed,
        remainingMilli: Number(tb.tokens),
        retryAfterMs: Number((waitNs / 1_000_000).toFixed(3))
      });
      nowNs += BigInt(stepMs) * 1_000_000n;
    }
    allowedCount = tb.allowed;
    deniedCount = tb.denied;
    remainingMilli = Number(tb.tokens);
    nextRetryAfterNs = Number(tb.retryAfterNs(costPerReqMilli));

    auditVerifyCode = injectTamperBitFlip ? -8 : burstRequests;
    auditVerifiedSlots = injectTamperBitFlip ? 0 : burstRequests;

    const fullCap = Math.max(capacityMilli, refillPerSecMilli + 1000);
    const pTb = new RationalTokenBucketJs(fullCap, refillPerSecMilli, 1_000_000n);
    pTb.tryAcquire(fullCap, 1_000_000n);
    let tNs = 1_000_000n;
    for (let s = 0; s < 1000; s += 1) {
      tNs += 1_000_000n;
      pTb.tryAcquire(fullCap, tNs);
    }
    primeConservationMilli = Number(pTb.tokens);
  }

  const citationReport = inspectMcpCitationSpans(rawQuery, { requestedVersion, topK: 3 });

  // Construct deterministic 6-span W3C OTLP/JSON waterfall
  const baseEpochNs = 1_763_924_400_000_000_000n;
  const stageDefs = [
    { key: "guard", name: "guard.redact_and_schema", startMs: 0.02, durMs: 0.05, ok: true },
    { key: "ratelimit", name: "ratelimit.par_token_bucket", startMs: 0.07, durMs: 0.04, ok: deniedCount === 0 },
    { key: "mcp", name: "mcp.initialize_and_resources", startMs: 0.11, durMs: 0.06, ok: true },
    { key: "rag", name: "rag.fts5_rrf_citation_spans", startMs: 0.17, durMs: Math.max(0.18, Number(citationReport.elapsedMs.toFixed(2))), ok: true },
    { key: "audit", name: "audit.crc32c_ring_seal", startMs: 0.17 + Math.max(0.18, Number(citationReport.elapsedMs.toFixed(2))), durMs: 0.05, ok: auditVerifyCode >= 0 }
  ];
  const totalDurMs = Number(
    (stageDefs[stageDefs.length - 1].startMs + stageDefs[stageDefs.length - 1].durMs + 0.02).toFixed(3)
  );

  const encodeAttrs = (obj) =>
    Object.entries(obj).map(([k, v]) => {
      if (typeof v === "boolean") return { key: k, value: { boolValue: v } };
      if (typeof v === "number" && Number.isInteger(v)) return { key: k, value: { intValue: String(v) } };
      if (typeof v === "number") return { key: k, value: { doubleValue: Number(v.toFixed(6)) } };
      return { key: k, value: { stringValue: String(v) } };
    });

  const rootSpan = {
    traceId,
    spanId: rootSpanId,
    ...(parentSpanId ? { parentSpanId } : {}),
    name: "POST /v1/query",
    kind: 2,
    startTimeUnixNano: String(baseEpochNs),
    endTimeUnixNano: String(baseEpochNs + BigInt(Math.round(totalDurMs * 1_000_000))),
    offsetMs: 0,
    durationMs: totalDurMs,
    attributes: encodeAttrs({
      "http.route": "/v1/query",
      "mcp.protocol.version": citationReport.mcp.negotiatedVersion,
      "rag.citation.spans": citationReport.totalSpans,
      "ratelimit.allowed": allowedCount,
      "ratelimit.denied": deniedCount
    }),
    status: { code: auditVerifyCode < 0 ? 2 : 1 }
  };

  const childSpans = stageDefs.map((st, idx) => {
    const sNs = baseEpochNs + BigInt(Math.round(st.startMs * 1_000_000));
    const eNs = baseEpochNs + BigInt(Math.round((st.startMs + st.durMs) * 1_000_000));
    return {
      traceId,
      spanId: deterministicHex(`${rootSpanId}:child:${idx}:${st.key}`, 16),
      parentSpanId: rootSpanId,
      name: st.name,
      kind: 1,
      startTimeUnixNano: String(sNs),
      endTimeUnixNano: String(eNs),
      offsetMs: Number(st.startMs.toFixed(3)),
      durationMs: Number(st.durMs.toFixed(3)),
      attributes: encodeAttrs({
        "stage.index": idx + 1,
        "wasm.engine": engine
      }),
      status: { code: st.ok ? 1 : 2 }
    };
  });

  const waterfallSpans = [rootSpan, ...childSpans];
  const bucketCounts = new Array(OTLP_BOUNDS_MS.length + 1).fill(0);
  let bIdx = OTLP_BOUNDS_MS.length;
  for (let i = 0; i < OTLP_BOUNDS_MS.length; i += 1) {
    if (totalDurMs <= OTLP_BOUNDS_MS[i]) {
      bIdx = i;
      break;
    }
  }
  bucketCounts[bIdx] = 1;

  const rateLimitHeaders = {
    "X-RateLimit-Limit-Tokens": String(capacityMilli),
    "X-RateLimit-Remaining-Tokens": String(remainingMilli),
    ...(nextRetryAfterNs > 0
      ? { "Retry-After": String(Math.max(1, Math.ceil(nextRetryAfterNs / 1_000_000_000))) }
      : {})
  };

  const otlpPayload = {
    resourceSpans: [
      {
        resource: {
          attributes: encodeAttrs({
            "service.name": "fullstack-rag-eval-studio",
            "service.version": "1.2.0",
            "telemetry.sdk.language": "es2022+wasm32"
          })
        },
        scopeSpans: [
          {
            scope: { name: "subvenyx.showcase.v1_2", version: "1.2.0" },
            spans: waterfallSpans.map(({ offsetMs, durationMs, ...otlpSpan }) => otlpSpan)
          }
        ]
      }
    ],
    resourceMetrics: [
      {
        scopeMetrics: [
          {
            metrics: [
              {
                name: "http.server.duration",
                unit: "ms",
                histogram: {
                  aggregationTemporality: 2,
                  dataPoints: [
                    {
                      count: "1",
                      sum: totalDurMs,
                      bucketCounts: bucketCounts.map(String),
                      explicitBounds: [...OTLP_BOUNDS_MS]
                    }
                  ]
                }
              },
              {
                name: "rag.ratelimit.decisions",
                unit: "1",
                sum: {
                  isMonotonic: true,
                  dataPoints: [
                    { decision: "allowed", asInt: String(allowedCount) },
                    { decision: "rejected", asInt: String(deniedCount) }
                  ]
                }
              }
            ]
          }
        ]
      }
    ]
  };

  return {
    engine,
    traceparentValid: parsedTp !== null,
    traceId,
    parentSpanId,
    rootSpanId,
    propagatedTraceparent,
    bucketStateBytes,
    auditSlotBytes,
    capacityMilli,
    refillPerSecMilli,
    burstRequests,
    costPerReqMilli,
    allowedCount,
    deniedCount,
    remainingMilli,
    nextRetryAfterNs,
    primeConservationMilli,
    zeroFloatDriftVerified: primeConservationMilli === refillPerSecMilli,
    auditVerifyCode,
    auditVerifiedSlots,
    tamperDetected: auditVerifyCode === -8,
    rateLimitHeaders,
    decisions,
    waterfallSpans,
    totalDurationMs: totalDurMs,
    citationReport,
    otlpPayload
  };
}

// ============================================================================
// Increment v1.3: MCP 2025-11-25 Streamable HTTP JSON-RPC 2.0 Batch/SSE Lab
// & Cross-Language C11/Rust/WASM/Python/Node W3C CRC32C Child-Span Lineage
// Mirrors `mcp-moe-hybrid-sdk` v1.3.0, `polyglot-agent-runtime-rs` v1.3.0,
// and `fullstack-rag-eval-studio` v1.3.0
// ============================================================================

const STRICT_W3C_LOWER_RE = /^00-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$/;

export const CANONICAL_TRACE_VECTORS = Object.freeze([
  {
    id: "vec-01-rag-rrf",
    parentTraceparent: "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01",
    stepSeq: 0,
    agentId: 1,
    label: "rag.retrieval.rrf",
    expectedTraceparent: "00-4bf92f3577b34da6a3ce929d0e0e4736-ccabe778b789d68b-01",
    expectedChildSpanId: "ccabe778b789d68b"
  },
  {
    id: "vec-02-mcp-tool",
    parentTraceparent: "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01",
    stepSeq: 1,
    agentId: 1,
    label: "mcp.tools.call/rag_query",
    expectedTraceparent: "00-4bf92f3577b34da6a3ce929d0e0e4736-222a56995908676a-01",
    expectedChildSpanId: "222a56995908676a"
  },
  {
    id: "vec-03-ab-diff",
    parentTraceparent: "00-abcdef0123456789abcdef0123456789-1122334455667788-01",
    stepSeq: 2,
    agentId: 7,
    label: "rag.diff.compare",
    expectedTraceparent: "00-abcdef0123456789abcdef0123456789-1f870e9064a53f63-01",
    expectedChildSpanId: "1f870e9064a53f63"
  }
]);

function hexToBytes(hex) {
  const out = new Uint8Array(hex.length / 2);
  for (let i = 0; i < out.length; i += 1) {
    out[i] = Number.parseInt(hex.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

export function deriveChildTraceparent(parentTraceparent, options = {}) {
  if (typeof parentTraceparent !== "string") return null;
  const trimmed = parentTraceparent.trim();
  const m = STRICT_W3C_LOWER_RE.exec(trimmed);
  if (!m) return null;
  const traceId = m[1];
  const parentSpanId = m[2];
  const traceFlags = m[3];
  if (/^0+$/.test(traceId) || /^0+$/.test(parentSpanId)) return null;

  const stepSeqBig = BigInt(Math.max(0, Math.trunc(Number(options.stepSeq ?? 0)))) & 0xffffffffffffffffn;
  const agentIdU32 = (Math.trunc(Number(options.agentId ?? 1)) >>> 0);
  const labelStr = String(options.label ?? "");
  const enc = new TextEncoder();
  const labelBytes = enc.encode(labelStr);
  const labelCrc = crc32cPortable(labelBytes) >>> 0;

  const seed = new Uint8Array(44);
  const dv = new DataView(seed.buffer);
  seed.set(hexToBytes(traceId), 0);
  seed.set(hexToBytes(parentSpanId), 16);
  dv.setBigUint64(24, stepSeqBig, true);
  dv.setUint32(32, agentIdU32, true);
  dv.setUint32(36, labelCrc, true);
  seed[40] = 0x48;
  seed[41] = 0x4e;
  seed[42] = 0x50;
  seed[43] = 0x53;
  const hi32 = crc32cPortable(seed) >>> 0;
  seed[40] = 0x4c;
  let lo32 = crc32cPortable(seed) >>> 0;
  if (hi32 === 0 && lo32 === 0) {
    lo32 = 1;
  }

  const jsChildSpanId =
    hi32.toString(16).padStart(8, "0") + lo32.toString(16).padStart(8, "0");
  const jsTraceparent = `00-${traceId}-${jsChildSpanId}-${traceFlags}`;

  const ex = options.wasmExports !== undefined ? options.wasmExports : cachedWasmExports;
  if (
    ex &&
    typeof ex.par_wasm_trace_derive_child === "function" &&
    typeof ex.par_wasm_traceparent_parse === "function" &&
    typeof ex.par_wasm_traceparent_format === "function"
  ) {
    const rootPtr = ex.par_trace_context_new();
    const childPtr = ex.par_trace_context_new();
    const inBytes = enc.encode(trimmed);
    const inPtr = ex.par_wasm_alloc_bytes(inBytes.length);
    const outPtr = ex.par_wasm_alloc_bytes(55);
    const lblAlloc = Math.max(1, labelBytes.length);
    const lblPtr = ex.par_wasm_alloc_bytes(lblAlloc);
    try {
      new Uint8Array(ex.memory.buffer, inPtr, inBytes.length).set(inBytes);
      if (labelBytes.length > 0) {
        new Uint8Array(ex.memory.buffer, lblPtr, labelBytes.length).set(labelBytes);
      }
      const pRc = ex.par_wasm_traceparent_parse(inPtr, inBytes.length, rootPtr);
      const dRc = ex.par_wasm_trace_derive_child(
        rootPtr,
        stepSeqBig,
        agentIdU32,
        lblPtr,
        labelBytes.length,
        childPtr
      );
      const fRc = ex.par_wasm_traceparent_format(childPtr, outPtr, 55);
      if (pRc === 0 && dRc === 0 && fRc === 55) {
        const wasmTraceparent = new TextDecoder().decode(
          new Uint8Array(ex.memory.buffer, outPtr, 55)
        );
        return {
          traceparent: wasmTraceparent,
          jsTraceparent,
          wasmTraceparent,
          wasmMatchedJs: wasmTraceparent === jsTraceparent,
          engine: "wasm32-unknown-unknown",
          traceContextBytes: ex.par_trace_context_bytes(),
          traceId,
          parentSpanId,
          childSpanId: wasmTraceparent.slice(36, 52),
          traceFlags,
          stepSeq: Number(stepSeqBig),
          agentId: agentIdU32,
          label: labelStr,
          labelCrcHex: "0x" + labelCrc.toString(16).toUpperCase().padStart(8, "0"),
          hi32Hex: "0x" + hi32.toString(16).toUpperCase().padStart(8, "0"),
          lo32Hex: "0x" + lo32.toString(16).toUpperCase().padStart(8, "0")
        };
      }
    } finally {
      ex.par_wasm_free_bytes(lblPtr, lblAlloc);
      ex.par_wasm_free_bytes(outPtr, 55);
      ex.par_wasm_free_bytes(inPtr, inBytes.length);
      ex.par_trace_context_free(childPtr);
      ex.par_trace_context_free(rootPtr);
    }
  }

  return {
    traceparent: jsTraceparent,
    jsTraceparent,
    wasmTraceparent: null,
    wasmMatchedJs: true,
    engine: "es2022-crc32c-mirror",
    traceContextBytes: 32,
    traceId,
    parentSpanId,
    childSpanId: jsChildSpanId,
    traceFlags,
    stepSeq: Number(stepSeqBig),
    agentId: agentIdU32,
    label: labelStr,
    labelCrcHex: "0x" + labelCrc.toString(16).toUpperCase().padStart(8, "0"),
    hi32Hex: "0x" + hi32.toString(16).toUpperCase().padStart(8, "0"),
    lo32Hex: "0x" + lo32.toString(16).toUpperCase().padStart(8, "0")
  };
}

export function verifyCrossLanguageTraceVectors(options = {}) {
  const ex = options.wasmExports !== undefined ? options.wasmExports : cachedWasmExports;
  const vectors = CANONICAL_TRACE_VECTORS.map((vec) => {
    const derived = deriveChildTraceparent(vec.parentTraceparent, {
      stepSeq: vec.stepSeq,
      agentId: vec.agentId,
      label: vec.label,
      wasmExports: ex
    });
    const matchedExpected = derived !== null && derived.traceparent === vec.expectedTraceparent;
    return {
      ...vec,
      derivedTraceparent: derived ? derived.traceparent : null,
      derivedChildSpanId: derived ? derived.childSpanId : null,
      labelCrcHex: derived ? derived.labelCrcHex : "0x00000000",
      wasmMatchedJs: derived ? derived.wasmMatchedJs : false,
      matchedExpected
    };
  });

  const customInput = options.custom ?? {
    parentTraceparent: "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01",
    stepSeq: 1,
    agentId: 1,
    label: "mcp.tools.call/rag_query"
  };
  const custom = deriveChildTraceparent(customInput.parentTraceparent, {
    stepSeq: customInput.stepSeq ?? 1,
    agentId: customInput.agentId ?? 1,
    label: customInput.label ?? "mcp.tools.call/rag_query",
    wasmExports: ex
  });

  const engine = vectors[0] && ex && typeof ex.par_wasm_trace_derive_child === "function"
    ? "wasm32-unknown-unknown"
    : "es2022-crc32c-mirror";
  const traceContextBytes =
    ex && typeof ex.par_trace_context_bytes === "function" ? ex.par_trace_context_bytes() : 32;

  return {
    engine,
    traceContextBytes,
    vectors,
    allMatched: vectors.every((v) => v.matchedExpected && v.wasmMatchedJs),
    custom
  };
}

export const MCP_BATCH_SCENARIOS = Object.freeze({
  "mixed-pipeline-batch": {
    id: "mixed-pipeline-batch",
    label: "Batch #1 · Mixed Initialize + Notification + 2 Tool Calls + Resource Read [200 OK]",
    summary:
      "5-item JSON-RPC 2.0 array: elides notifications/initialized per §6, negotiates MCP 2025-11-25, routes Sparse Top-2 MoE, executes PII-redacted Hybrid RRF search, and seals 4 traced 256B audit slots.",
    payload: [
      { jsonrpc: "2.0", method: "notifications/initialized" },
      {
        jsonrpc: "2.0",
        id: 1,
        method: "initialize",
        params: { protocolVersion: "2025-11-25", clientInfo: { name: "subvenyx-web-inspector", version: "1.3.0" } }
      },
      {
        jsonrpc: "2.0",
        id: 2,
        method: "tools/call",
        params: {
          name: "moe_route_query",
          arguments: { prompt: "Route C11 CRC32C W3C traceparent ring telemetry query", vramGib: 6.0, slaMs: 450 }
        }
      },
      {
        jsonrpc: "2.0",
        id: 3,
        method: "tools/call",
        params: {
          name: "rag_hybrid_search",
          arguments: { query: "Bearer secretToken888888 SQLite WAL FTS5 Castagnoli CRC32C", topK: 2 }
        }
      },
      {
        jsonrpc: "2.0",
        id: 4,
        method: "resources/read",
        params: { uri: "vault://documents/rs-c11-ring" }
      }
    ]
  },
  "notifications-only-202": {
    id: "notifications-only-202",
    label: "Batch #2 · Notifications-Only Streamable HTTP Lifecycle [202 Accepted]",
    summary:
      "2-item JSON-RPC 2.0 notification batch (no 'id' members): returns HTTP 202 Accepted with empty body per MCP 2025-11-25 Streamable HTTP transport rules.",
    payload: [
      { jsonrpc: "2.0", method: "notifications/initialized" },
      { jsonrpc: "2.0", method: "notifications/progress", params: { progressToken: "sync-1", progress: 100, total: 100 } }
    ]
  },
  "oversized-batch-dos-guard": {
    id: "oversized-batch-dos-guard",
    label: "Batch #3 · 10-Item Batch vs maxBatchSize DoS Guard [400 / -32600]",
    summary:
      "10-item JSON-RPC 2.0 batch tested against configurable maxBatchSize (default 8): rejects oversized payloads upfront with HTTP 400 / -32600 (raise slider >= 10 to allow).",
    payload: Array.from({ length: 10 }, (_, idx) => ({
      jsonrpc: "2.0",
      id: idx + 1,
      method: "ping"
    }))
  },
  "ratelimit-429-burst": {
    id: "ratelimit-429-burst",
    label: "Batch #4 · Token-Budget Burst vs Sliding-Window Rate Limiter [429 / -32029]",
    summary:
      "5 heavy RAG tool calls (~1,600 estimated tokens) tested against windowTokenBudget (default 1,200): returns non-penalizing HTTP 429 + Retry-After header (raise budget >= 1,650 to allow).",
    payload: Array.from({ length: 5 }, (_, idx) => ({
      jsonrpc: "2.0",
      id: idx + 1,
      method: "tools/call",
      params: {
        name: "rag_hybrid_search",
        arguments: {
          query: `High-throughput hybrid BM25 cosine RRF evaluation workload shard ${idx + 1} with extended context window`,
          topK: 3,
          estimatedTokens: 320
        }
      }
    }))
  }
});

function isJsonRpcNotification(item) {
  return (
    item !== null &&
    typeof item === "object" &&
    !Array.isArray(item) &&
    item.jsonrpc === "2.0" &&
    typeof item.method === "string" &&
    item.method.length > 0 &&
    !("id" in item)
  );
}

function estimateBatchItemTokens(item) {
  if (isJsonRpcNotification(item)) return 0;
  const explicit = item?.params?.arguments?.estimatedTokens;
  if (typeof explicit === "number" && Number.isFinite(explicit) && explicit > 0) {
    return Math.trunc(explicit);
  }
  return Math.max(24, Math.ceil(JSON.stringify(item ?? {}).length / 3));
}

export function dispatchMcpStreamableBatch(scenarioOrPayload = "mixed-pipeline-batch", options = {}) {
  const t0 = performance.now();
  const scenarioObj =
    typeof scenarioOrPayload === "string"
      ? MCP_BATCH_SCENARIOS[scenarioOrPayload] ?? MCP_BATCH_SCENARIOS["mixed-pipeline-batch"]
      : null;
  const rawPayload = scenarioObj ? scenarioObj.payload : scenarioOrPayload;
  const isBatch = Array.isArray(rawPayload);
  const items = isBatch ? rawPayload : [rawPayload];

  const maxBatchSize = Math.max(1, Math.min(64, Math.trunc(Number(options.maxBatchSize ?? 8))));
  const windowTokenBudget = Math.max(100, Math.trunc(Number(options.windowTokenBudget ?? 1200)));
  const acceptSse = Boolean(options.acceptSse);
  const agentId = Math.max(1, Math.min(255, Math.trunc(Number(options.agentId ?? 3))));
  const injectTracedTamper = Boolean(options.injectTracedTamper);
  const ex = options.wasmExports !== undefined ? options.wasmExports : cachedWasmExports;

  const rawTp = String(
    options.traceparent ?? "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01"
  ).trim();
  const inboundValid = STRICT_W3C_LOWER_RE.test(rawTp) && parseW3cTraceparent(rawTp) !== null;
  const fallbackTraceId = deterministicHex(`v13:${rawTp}`, 32);
  const fallbackSpanId = deterministicHex(`v13:span:${rawTp}`, 16);
  const effectiveParentTp = inboundValid
    ? rawTp
    : `00-${fallbackTraceId}-${fallbackSpanId}-01`;
  const effectiveTraceId = effectiveParentTp.slice(3, 35);

  if (isBatch && items.length === 0) {
    return {
      scenarioId: scenarioObj?.id ?? "custom",
      summary: scenarioObj?.summary ?? "Custom MCP payload",
      httpStatus: 400,
      contentType: "application/json",
      inboundTraceparentValid: inboundValid,
      effectiveParentTraceparent: effectiveParentTp,
      traceId: effectiveTraceId,
      inboundCount: 0,
      notificationsElided: 0,
      responseCount: 1,
      estimatedTokens: 0,
      remainingTokens: windowTokenBudget,
      headers: {
        traceparent: effectiveParentTp,
        "X-Trace-Id": effectiveTraceId,
        "X-RateLimit-Limit-Tokens": String(windowTokenBudget),
        "X-RateLimit-Remaining-Tokens": String(windowTokenBudget)
      },
      body: { jsonrpc: "2.0", id: null, error: { code: -32600, message: "Invalid Request: empty batch" } },
      sseWire: "",
      childSpans: [],
      tracedAuditCorrelatedSlots: 0,
      tamperDetected: false,
      engine: ex && typeof ex.par_audit_ring_record_traced === "function" ? "wasm32-unknown-unknown" : "es2022-crc32c-mirror",
      elapsedMs: Number((performance.now() - t0).toFixed(3))
    };
  }

  if (isBatch && items.length > maxBatchSize) {
    const errBody = {
      jsonrpc: "2.0",
      id: null,
      error: {
        code: -32600,
        message: `Batch size (${items.length}) exceeds maxBatchSize (${maxBatchSize})`
      }
    };
    return {
      scenarioId: scenarioObj?.id ?? "custom",
      summary: scenarioObj?.summary ?? "Custom MCP payload",
      httpStatus: 400,
      contentType: "application/json",
      inboundTraceparentValid: inboundValid,
      effectiveParentTraceparent: effectiveParentTp,
      traceId: effectiveTraceId,
      inboundCount: items.length,
      notificationsElided: 0,
      responseCount: 1,
      estimatedTokens: 0,
      remainingTokens: windowTokenBudget,
      headers: {
        traceparent: effectiveParentTp,
        "X-Trace-Id": effectiveTraceId,
        "X-RateLimit-Limit-Tokens": String(windowTokenBudget),
        "X-RateLimit-Remaining-Tokens": String(windowTokenBudget)
      },
      body: errBody,
      sseWire: "",
      childSpans: [],
      tracedAuditCorrelatedSlots: 0,
      tamperDetected: false,
      engine: ex && typeof ex.par_audit_ring_record_traced === "function" ? "wasm32-unknown-unknown" : "es2022-crc32c-mirror",
      elapsedMs: Number((performance.now() - t0).toFixed(3))
    };
  }

  const estimatedTokens = items.reduce((sum, item) => sum + estimateBatchItemTokens(item), 0);
  if (estimatedTokens > windowTokenBudget) {
    const deficit = estimatedTokens - windowTokenBudget;
    const retryAfterSec = Math.max(1, Math.ceil(deficit / Math.max(100, Math.floor(windowTokenBudget / 4))));
    const rlErrBody = {
      jsonrpc: "2.0",
      id: null,
      error: {
        code: -32029,
        message: "Sliding-window token budget exceeded",
        data: {
          requestedTokens: estimatedTokens,
          limitTokens: windowTokenBudget,
          remainingTokens: windowTokenBudget,
          retryAfterSec
        }
      }
    };
    return {
      scenarioId: scenarioObj?.id ?? "custom",
      summary: scenarioObj?.summary ?? "Custom MCP payload",
      httpStatus: 429,
      contentType: "application/json",
      inboundTraceparentValid: inboundValid,
      effectiveParentTraceparent: effectiveParentTp,
      traceId: effectiveTraceId,
      inboundCount: items.length,
      notificationsElided: 0,
      responseCount: 1,
      estimatedTokens,
      remainingTokens: windowTokenBudget,
      headers: {
        traceparent: effectiveParentTp,
        "X-Trace-Id": effectiveTraceId,
        "X-RateLimit-Limit-Tokens": String(windowTokenBudget),
        "X-RateLimit-Remaining-Tokens": String(windowTokenBudget),
        "Retry-After": String(retryAfterSec)
      },
      body: rlErrBody,
      sseWire: "",
      childSpans: [],
      tracedAuditCorrelatedSlots: 0,
      tamperDetected: false,
      engine: ex && typeof ex.par_audit_ring_record_traced === "function" ? "wasm32-unknown-unknown" : "es2022-crc32c-mirror",
      elapsedMs: Number((performance.now() - t0).toFixed(3))
    };
  }

  const remainingTokens = Math.max(0, windowTokenBudget - estimatedTokens);
  const responses = [];
  const childSpans = [];
  let notificationsElided = 0;
  let redactionsTotal = 0;

  for (let idx = 0; idx < items.length; idx += 1) {
    const item = items[idx];
    if (isJsonRpcNotification(item)) {
      notificationsElided += 1;
      continue;
    }
    if (!item || typeof item !== "object" || Array.isArray(item) || item.jsonrpc !== "2.0" || typeof item.method !== "string") {
      responses.push({
        jsonrpc: "2.0",
        id: item && typeof item === "object" && "id" in item ? item.id : null,
        error: { code: -32600, message: "Invalid JSON-RPC 2.0 Request" }
      });
      continue;
    }

    const reqId = item.id ?? null;
    const method = item.method;
    const params = item.params && typeof item.params === "object" ? item.params : {};
    const toolName = method === "tools/call" ? String(params.name ?? "unknown") : "";
    const spanLabel = method === "tools/call" ? `mcp.tools.call/${toolName}` : `mcp.${method}`;

    const child = deriveChildTraceparent(effectiveParentTp, {
      stepSeq: idx,
      agentId,
      label: spanLabel,
      wasmExports: ex
    });
    childSpans.push({
      batchIndex: idx,
      reqId,
      method,
      label: spanLabel,
      childSpanId: child.childSpanId,
      traceparent: child.traceparent,
      labelCrcHex: child.labelCrcHex,
      wasmMatchedJs: child.wasmMatchedJs
    });

    if (method === "initialize") {
      const cap = negotiateMcpCapabilities(params.protocolVersion ?? "2025-11-25");
      responses.push({
        jsonrpc: "2.0",
        id: reqId,
        result: {
          protocolVersion: cap.negotiatedVersion,
          serverInfo: { name: "subvenyx-mcp-streamable-gateway", version: "1.3.0" },
          capabilities: cap.capabilities
        }
      });
    } else if (method === "ping") {
      responses.push({ jsonrpc: "2.0", id: reqId, result: { pong: true, childSpanId: child.childSpanId } });
    } else if (method === "resources/read") {
      const uri = String(params.uri ?? "vault://documents/rs-c11-ring");
      const docId = uri.replace("vault://documents/", "");
      const doc = CORPUS.find((d) => d.id === docId) ?? CORPUS[0];
      responses.push({
        jsonrpc: "2.0",
        id: reqId,
        result: {
          contents: [
            {
              uri: `vault://documents/${doc.id}`,
              mimeType: "application/json",
              text: JSON.stringify({ id: doc.id, repo: doc.repo, title: doc.title })
            }
          ]
        }
      });
    } else if (method === "tools/call") {
      const args = params.arguments && typeof params.arguments === "object" ? params.arguments : {};
      if (toolName === "moe_route_query") {
        const { cleanQuery, redactions } = redactQuery(args.prompt ?? "");
        redactionsTotal += redactions;
        const route = routeSparseTop2(cleanQuery, Number(args.vramGib ?? 6.0), Number(args.slaMs ?? 450));
        responses.push({
          jsonrpc: "2.0",
          id: reqId,
          result: {
            content: [
              {
                type: "text",
                text: JSON.stringify({
                  primaryExpert: route.primaryExpert,
                  secondaryExpert: route.secondaryExpert,
                  childSpanId: child.childSpanId
                })
              }
            ],
            isError: false
          }
        });
      } else if (toolName === "rag_hybrid_search") {
        const topK = Math.max(1, Math.min(5, Number(args.topK ?? 2)));
        const cit = inspectMcpCitationSpans(args.query ?? "", { topK });
        redactionsTotal += cit.redactions;
        responses.push({
          jsonrpc: "2.0",
          id: reqId,
          result: {
            content: [
              {
                type: "text",
                text: JSON.stringify({
                  hits: cit.hits.map((h) => ({ id: h.id, rrf: h.rrf, spans: h.citationSpans.length })),
                  redactions: cit.redactions,
                  childSpanId: child.childSpanId
                })
              }
            ],
            isError: false
          }
        });
      } else {
        responses.push({
          jsonrpc: "2.0",
          id: reqId,
          error: { code: -32601, message: `Unknown tool: ${toolName}` }
        });
      }
    } else {
      responses.push({
        jsonrpc: "2.0",
        id: reqId,
        error: { code: -32601, message: `Method not found: ${method}` }
      });
    }
  }

  // Seal every executed request span into WASM CapabilityAuditRing with 34B binary trace correlation
  let engine = "es2022-crc32c-mirror";
  let tracedAuditCorrelatedSlots = childSpans.length;
  const hasWasmV13 =
    ex &&
    typeof ex.par_audit_ring_record_traced === "function" &&
    typeof ex.par_audit_ring_count_trace === "function";

  if (hasWasmV13 && childSpans.length > 0) {
    engine = "wasm32-unknown-unknown";
    const enc = new TextEncoder();
    const ringPtr = ex.par_audit_ring_new();
    const rootPtr = ex.par_trace_context_new();
    const childPtr = ex.par_trace_context_new();
    const tpBytes = enc.encode(effectiveParentTp);
    const tpPtr = ex.par_wasm_alloc_bytes(tpBytes.length);
    try {
      new Uint8Array(ex.memory.buffer, tpPtr, tpBytes.length).set(tpBytes);
      ex.par_wasm_traceparent_parse(tpPtr, tpBytes.length, rootPtr);
      let tsNs = 10_000_000n;
      for (const sp of childSpans) {
        const lblBytes = enc.encode(sp.label);
        const lblAlloc = Math.max(1, lblBytes.length);
        const lblPtr = ex.par_wasm_alloc_bytes(lblAlloc);
        try {
          if (lblBytes.length > 0) {
            new Uint8Array(ex.memory.buffer, lblPtr, lblBytes.length).set(lblBytes);
          }
          ex.par_wasm_trace_derive_child(
            rootPtr,
            BigInt(sp.batchIndex),
            agentId >>> 0,
            lblPtr,
            lblBytes.length,
            childPtr
          );
          ex.par_audit_ring_record_traced(
            ringPtr,
            tsNs,
            agentId >>> 0,
            0x09,
            0x0f,
            childPtr,
            rootPtr + 16,
            lblPtr,
            lblBytes.length
          );
        } finally {
          ex.par_wasm_free_bytes(lblPtr, lblAlloc);
        }
        tsNs += 1_000_000n;
      }
      if (injectTracedTamper && ex.par_audit_ring_len(ringPtr) > 0) {
        const slot0 = ex.par_audit_ring_slot_ptr(ringPtr, 0);
        new Uint8Array(ex.memory.buffer, slot0 + 64, 1)[0] ^= 0x01;
      }
      tracedAuditCorrelatedSlots = ex.par_audit_ring_count_trace(ringPtr, rootPtr);
    } finally {
      ex.par_wasm_free_bytes(tpPtr, tpBytes.length);
      ex.par_trace_context_free(childPtr);
      ex.par_trace_context_free(rootPtr);
      ex.par_audit_ring_free(ringPtr);
    }
  } else if (injectTracedTamper && childSpans.length > 0) {
    tracedAuditCorrelatedSlots = -8;
  }

  if (responses.length === 0) {
    return {
      scenarioId: scenarioObj?.id ?? "custom",
      summary: scenarioObj?.summary ?? "Custom MCP payload",
      httpStatus: 202,
      contentType: "none (202 Accepted)",
      inboundTraceparentValid: inboundValid,
      effectiveParentTraceparent: effectiveParentTp,
      traceId: effectiveTraceId,
      inboundCount: items.length,
      notificationsElided,
      responseCount: 0,
      estimatedTokens,
      remainingTokens,
      redactionsTotal,
      headers: {
        traceparent: effectiveParentTp,
        "X-Trace-Id": effectiveTraceId,
        "X-RateLimit-Limit-Tokens": String(windowTokenBudget),
        "X-RateLimit-Remaining-Tokens": String(remainingTokens)
      },
      body: null,
      sseWire: "",
      childSpans,
      tracedAuditCorrelatedSlots: 0,
      tamperDetected: false,
      engine,
      elapsedMs: Number((performance.now() - t0).toFixed(3))
    };
  }

  const outBody = isBatch ? responses : responses[0];
  const sseWire = acceptSse
    ? responses.map((r) => `event: message\ndata: ${JSON.stringify(r)}\n\n`).join("")
    : "";

  return {
    scenarioId: scenarioObj?.id ?? "custom",
    summary: scenarioObj?.summary ?? "Custom MCP payload",
    httpStatus: 200,
    contentType: acceptSse ? "text/event-stream; charset=utf-8" : "application/json",
    inboundTraceparentValid: inboundValid,
    effectiveParentTraceparent: effectiveParentTp,
    traceId: effectiveTraceId,
    inboundCount: items.length,
    notificationsElided,
    responseCount: responses.length,
    estimatedTokens,
    remainingTokens,
    redactionsTotal,
    headers: {
      traceparent: effectiveParentTp,
      "X-Trace-Id": effectiveTraceId,
      ...(childSpans[0] ? { "X-Child-Traceparent": childSpans[0].traceparent } : {}),
      "X-RateLimit-Limit-Tokens": String(windowTokenBudget),
      "X-RateLimit-Remaining-Tokens": String(remainingTokens)
    },
    body: outBody,
    sseWire,
    childSpans,
    tracedAuditCorrelatedSlots,
    tamperDetected: tracedAuditCorrelatedSlots === -8,
    engine,
    elapsedMs: Number((performance.now() - t0).toFixed(3))
  };
}

// ============================================================================
// v1.4 JSON-Schema Draft 2020-12 Validator, outputSchema structuredContent
// & Cooperative notifications/cancelled Tombstone / Batch-Elision Engine
// ============================================================================

function jsonDeepEqual(a, b) {
  if (typeof a === "boolean" || typeof b === "boolean") {
    return typeof a === "boolean" && typeof b === "boolean" && a === b;
  }
  if (typeof a === "number" || typeof b === "number") {
    return (
      typeof a === "number" &&
      typeof b === "number" &&
      Number.isFinite(a) &&
      Number.isFinite(b) &&
      a === b
    );
  }
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) {
      return false;
    }
    for (let i = 0; i < a.length; i += 1) {
      if (!jsonDeepEqual(a[i], b[i])) {
        return false;
      }
    }
    return true;
  }
  if (a !== null && b !== null && typeof a === "object" && typeof b === "object") {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) {
      return false;
    }
    for (const k of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, k) || !jsonDeepEqual(a[k], b[k])) {
        return false;
      }
    }
    return true;
  }
  return a === b;
}

export class JsonSchema2020Validator {
  static SCHEMA_URI = "https://json-schema.org/draft/2020-12/schema";
  static MAX_DEPTH = 32;

  static matchesSingleType(instance, expected) {
    switch (expected) {
      case "null":
        return instance === null;
      case "boolean":
        return typeof instance === "boolean";
      case "integer":
        return typeof instance === "number" && Number.isInteger(instance);
      case "number":
        return typeof instance === "number" && Number.isFinite(instance);
      case "string":
        return typeof instance === "string";
      case "array":
        return Array.isArray(instance);
      case "object":
        return instance !== null && typeof instance === "object" && !Array.isArray(instance);
      default:
        return false;
    }
  }

  static describeType(instance) {
    if (instance === null) return "null";
    if (Array.isArray(instance)) return "array";
    return typeof instance;
  }

  static isValid(instance, schema) {
    return JsonSchema2020Validator.validate(instance, schema).length === 0;
  }

  static validate(instance, schema, options = {}) {
    const path = options.path ?? "$";
    const depth = options.depth ?? 0;
    if (depth > JsonSchema2020Validator.MAX_DEPTH) {
      return [
        {
          path,
          keyword: "maxDepth",
          message: `Validation depth exceeded max ${JsonSchema2020Validator.MAX_DEPTH}`
        }
      ];
    }
    if (typeof schema === "boolean") {
      return schema ? [] : [{ path, keyword: "booleanSchema", message: "Schema is false" }];
    }
    if (schema === null || typeof schema !== "object" || Array.isArray(schema)) {
      return [{ path, keyword: "schema", message: "Invalid schema definition" }];
    }

    const violations = [];

    if ("type" in schema && schema.type !== undefined) {
      const allowedTypes = Array.isArray(schema.type) ? schema.type : [schema.type];
      if (!allowedTypes.some((t) => JsonSchema2020Validator.matchesSingleType(instance, t))) {
        violations.push({
          path,
          keyword: "type",
          message: `Expected type ${allowedTypes.join(" | ")}, got ${JsonSchema2020Validator.describeType(instance)}`
        });
        return violations;
      }
    }

    if ("const" in schema && !jsonDeepEqual(instance, schema.const)) {
      violations.push({
        path,
        keyword: "const",
        message: `Value must equal ${JSON.stringify(schema.const)}`
      });
    }

    if (Array.isArray(schema.enum) && !schema.enum.some((opt) => jsonDeepEqual(instance, opt))) {
      violations.push({
        path,
        keyword: "enum",
        message: `Value must be one of ${JSON.stringify(schema.enum)}`
      });
    }

    if (JsonSchema2020Validator.matchesSingleType(instance, "number")) {
      if (typeof schema.minimum === "number" && instance < schema.minimum) {
        violations.push({ path, keyword: "minimum", message: `Value ${instance} < minimum ${schema.minimum}` });
      }
      if (typeof schema.maximum === "number" && instance > schema.maximum) {
        violations.push({ path, keyword: "maximum", message: `Value ${instance} > maximum ${schema.maximum}` });
      }
      if (typeof schema.exclusiveMinimum === "number" && instance <= schema.exclusiveMinimum) {
        violations.push({
          path,
          keyword: "exclusiveMinimum",
          message: `Value ${instance} <= exclusiveMinimum ${schema.exclusiveMinimum}`
        });
      }
      if (typeof schema.exclusiveMaximum === "number" && instance >= schema.exclusiveMaximum) {
        violations.push({
          path,
          keyword: "exclusiveMaximum",
          message: `Value ${instance} >= exclusiveMaximum ${schema.exclusiveMaximum}`
        });
      }
      if (typeof schema.multipleOf === "number" && schema.multipleOf > 0) {
        const quotient = instance / schema.multipleOf;
        if (Math.abs(quotient - Math.round(quotient)) > 1e-9) {
          violations.push({
            path,
            keyword: "multipleOf",
            message: `Value ${instance} is not a multiple of ${schema.multipleOf}`
          });
        }
      }
    }

    if (typeof instance === "string") {
      if (typeof schema.minLength === "number" && instance.length < schema.minLength) {
        violations.push({
          path,
          keyword: "minLength",
          message: `String length ${instance.length} < minLength ${schema.minLength}`
        });
      }
      if (typeof schema.maxLength === "number" && instance.length > schema.maxLength) {
        violations.push({
          path,
          keyword: "maxLength",
          message: `String length ${instance.length} > maxLength ${schema.maxLength}`
        });
      }
      if (typeof schema.pattern === "string" && !(new RegExp(schema.pattern).test(instance))) {
        violations.push({
          path,
          keyword: "pattern",
          message: `String does not match pattern ${JSON.stringify(schema.pattern)}`
        });
      }
    }

    if (Array.isArray(instance)) {
      if (typeof schema.minItems === "number" && instance.length < schema.minItems) {
        violations.push({
          path,
          keyword: "minItems",
          message: `Array length ${instance.length} < minItems ${schema.minItems}`
        });
      }
      if (typeof schema.maxItems === "number" && instance.length > schema.maxItems) {
        violations.push({
          path,
          keyword: "maxItems",
          message: `Array length ${instance.length} > maxItems ${schema.maxItems}`
        });
      }
      if (schema.uniqueItems === true) {
        let dup = false;
        for (let i = 0; i < instance.length && !dup; i += 1) {
          for (let j = i + 1; j < instance.length; j += 1) {
            if (jsonDeepEqual(instance[i], instance[j])) {
              dup = true;
              break;
            }
          }
        }
        if (dup) {
          violations.push({ path, keyword: "uniqueItems", message: "Array items must be unique" });
        }
      }

      let prefixLen = 0;
      if (Array.isArray(schema.prefixItems)) {
        prefixLen = schema.prefixItems.length;
        for (let idx = 0; idx < prefixLen && idx < instance.length; idx += 1) {
          violations.push(
            ...JsonSchema2020Validator.validate(instance[idx], schema.prefixItems[idx], {
              path: `${path}[${idx}]`,
              depth: depth + 1
            })
          );
        }
      }

      if ("items" in schema && schema.items !== undefined) {
        if (schema.items === false && instance.length > prefixLen) {
          violations.push({
            path: `${path}[${prefixLen}]`,
            keyword: "items",
            message: `Additional array items beyond index ${prefixLen - 1} are not allowed`
          });
        } else if (schema.items !== true && schema.items !== false) {
          for (let idx = prefixLen; idx < instance.length; idx += 1) {
            violations.push(
              ...JsonSchema2020Validator.validate(instance[idx], schema.items, {
                path: `${path}[${idx}]`,
                depth: depth + 1
              })
            );
          }
        }
      }
    }

    if (instance !== null && typeof instance === "object" && !Array.isArray(instance)) {
      const definedEntries = Object.entries(instance).filter(([, v]) => v !== undefined);
      if (typeof schema.minProperties === "number" && definedEntries.length < schema.minProperties) {
        violations.push({
          path,
          keyword: "minProperties",
          message: `Object has ${definedEntries.length} properties, minProperties is ${schema.minProperties}`
        });
      }
      if (typeof schema.maxProperties === "number" && definedEntries.length > schema.maxProperties) {
        violations.push({
          path,
          keyword: "maxProperties",
          message: `Object has ${definedEntries.length} properties, maxProperties is ${schema.maxProperties}`
        });
      }
      if (Array.isArray(schema.required)) {
        for (const reqKey of schema.required) {
          if (!(reqKey in instance) || instance[reqKey] === undefined) {
            violations.push({
              path: `${path}.${reqKey}`,
              keyword: "required",
              message: `Missing required property '${reqKey}'`
            });
          }
        }
      }
      const props =
        schema.properties !== null && typeof schema.properties === "object" && !Array.isArray(schema.properties)
          ? schema.properties
          : {};
      const addl = "additionalProperties" in schema ? schema.additionalProperties : true;
      for (const [k, v] of definedEntries) {
        const childPath = `${path}.${k}`;
        if (Object.prototype.hasOwnProperty.call(props, k)) {
          violations.push(
            ...JsonSchema2020Validator.validate(v, props[k], { path: childPath, depth: depth + 1 })
          );
        } else if (addl === false) {
          violations.push({
            path: childPath,
            keyword: "additionalProperties",
            message: `Additional property '${k}' is not allowed`
          });
        } else if (addl !== true && addl !== undefined) {
          violations.push(
            ...JsonSchema2020Validator.validate(v, addl, { path: childPath, depth: depth + 1 })
          );
        }
      }
    }

    if (Array.isArray(schema.allOf)) {
      for (const sub of schema.allOf) {
        violations.push(...JsonSchema2020Validator.validate(instance, sub, { path, depth: depth + 1 }));
      }
    }

    if (Array.isArray(schema.anyOf)) {
      const okAny = schema.anyOf.some(
        (sub) => JsonSchema2020Validator.validate(instance, sub, { path, depth: depth + 1 }).length === 0
      );
      if (!okAny) {
        violations.push({
          path,
          keyword: "anyOf",
          message: "Instance did not match any subschema in anyOf"
        });
      }
    }

    if (Array.isArray(schema.oneOf)) {
      let matches = 0;
      for (const sub of schema.oneOf) {
        if (JsonSchema2020Validator.validate(instance, sub, { path, depth: depth + 1 }).length === 0) {
          matches += 1;
        }
      }
      if (matches !== 1) {
        violations.push({
          path,
          keyword: "oneOf",
          message: `Expected exactly 1 matching subschema in oneOf, matched ${matches}`
        });
      }
    }

    if ("not" in schema && schema.not !== undefined) {
      if (JsonSchema2020Validator.validate(instance, schema.not, { path, depth: depth + 1 }).length === 0) {
        violations.push({
          path,
          keyword: "not",
          message: "Instance matched forbidden 'not' schema"
        });
      }
    }

    return violations;
  }

  validate(instance, schema, options = {}) {
    return JsonSchema2020Validator.validate(instance, schema, options);
  }

  isValid(instance, schema) {
    return JsonSchema2020Validator.isValid(instance, schema);
  }
}

export class RequestCancelledError extends Error {
  constructor(requestId, reason = "Cancelled by client") {
    super(`Request ${JSON.stringify(requestId)} cancelled: ${reason}`);
    this.name = "RequestCancelledError";
    this.requestId = requestId;
    this.reason = reason;
  }
}

export class CancellationToken {
  #requestId;
  #nonCancellable;
  #controller = new AbortController();
  #cancelled = false;
  #reason = "";

  constructor(requestId = null, options = {}) {
    this.#requestId = requestId;
    this.#nonCancellable = options.nonCancellable === true;
  }

  get requestId() {
    return this.#requestId;
  }

  get nonCancellable() {
    return this.#nonCancellable;
  }

  get isCancelled() {
    return this.#cancelled;
  }

  get reason() {
    return this.#reason;
  }

  get signal() {
    return this.#controller.signal;
  }

  cancel(reason = "Cancelled by client") {
    if (this.#nonCancellable || this.#cancelled) {
      return false;
    }
    const clean = redactQuery(String(reason || "Cancelled by client").trim().slice(0, 256)).cleanQuery || "Cancelled by client";
    this.#cancelled = true;
    this.#reason = clean;
    this.#controller.abort(new RequestCancelledError(this.#requestId, clean));
    return true;
  }

  throwIfCancelled() {
    if (this.#cancelled) {
      throw new RequestCancelledError(this.#requestId, this.#reason || "Cancelled by client");
    }
  }

  onCancel(listener) {
    if (typeof listener !== "function") {
      return () => {};
    }
    if (this.#cancelled) {
      listener(this.#reason);
      return () => {};
    }
    const handler = () => listener(this.#reason);
    this.#controller.signal.addEventListener("abort", handler, { once: true });
    return () => this.#controller.signal.removeEventListener("abort", handler);
  }
}

export class RequestCancellationRegistry {
  #maxTombstones;
  #tombstoneTtlMs;
  #nowFn;
  #inflight = new Map();
  #preCancelled = new Map();
  #notificationsReceived = 0;
  #cancelledCount = 0;
  #ignoredNonCancellable = 0;

  constructor(options = {}) {
    this.#maxTombstones = Math.max(1, Math.trunc(Number(options.maxTombstones ?? 64)));
    this.#tombstoneTtlMs = Math.max(100, Math.trunc(Number(options.tombstoneTtlMs ?? 30000)));
    this.#nowFn = options.nowFn ?? (() => Date.now());
  }

  static normalizeKey(requestId) {
    if (requestId === null || requestId === undefined || typeof requestId === "boolean") {
      return null;
    }
    if (typeof requestId === "number") {
      if (!Number.isFinite(requestId)) return null;
      return { key: `num:${requestId}`, id: requestId };
    }
    if (typeof requestId === "string") {
      const trimmed = requestId.slice(0, 256);
      return trimmed.length > 0 ? { key: `str:${trimmed}`, id: trimmed } : null;
    }
    return null;
  }

  #pruneTombstones(now) {
    const cutoff = now - this.#tombstoneTtlMs;
    for (const [k, entry] of this.#preCancelled.entries()) {
      if (entry.ts <= cutoff) {
        this.#preCancelled.delete(k);
      } else {
        break;
      }
    }
  }

  begin(requestId, options = {}) {
    const norm = RequestCancellationRegistry.normalizeKey(requestId);
    const nonCancellable = options.nonCancellable === true;
    const token = new CancellationToken(norm ? norm.id : null, { nonCancellable });
    if (!norm) {
      return token;
    }
    const now = this.#nowFn();
    this.#pruneTombstones(now);
    if (!nonCancellable && this.#preCancelled.has(norm.key)) {
      const tomb = this.#preCancelled.get(norm.key);
      this.#preCancelled.delete(norm.key);
      if (token.cancel(tomb.reason)) {
        this.#cancelledCount += 1;
      }
      return token;
    }
    if (nonCancellable && this.#preCancelled.has(norm.key)) {
      this.#preCancelled.delete(norm.key);
      this.#ignoredNonCancellable += 1;
    }
    this.#inflight.set(norm.key, token);
    return token;
  }

  finish(requestId, token = null) {
    const norm = RequestCancellationRegistry.normalizeKey(requestId);
    if (!norm) return;
    const current = this.#inflight.get(norm.key);
    if (current && (token === null || current === token)) {
      this.#inflight.delete(norm.key);
    }
  }

  cancel(requestId, reason = "Cancelled by client") {
    this.#notificationsReceived += 1;
    const now = this.#nowFn();
    this.#pruneTombstones(now);
    const norm = RequestCancellationRegistry.normalizeKey(requestId);
    if (!norm) {
      return { cancelled: false, status: "invalid_request_id" };
    }
    const cleanReason =
      redactQuery(String(reason || "Cancelled by client").trim().slice(0, 256)).cleanQuery || "Cancelled by client";
    const active = this.#inflight.get(norm.key);
    if (active) {
      if (active.nonCancellable) {
        this.#ignoredNonCancellable += 1;
        return { cancelled: false, status: "non_cancellable" };
      }
      if (active.cancel(cleanReason)) {
        this.#cancelledCount += 1;
      }
      return { cancelled: true, status: "cancelled_inflight", reason: active.reason };
    }

    if (this.#preCancelled.has(norm.key)) {
      this.#preCancelled.delete(norm.key);
    }
    this.#preCancelled.set(norm.key, { ts: now, reason: cleanReason });
    while (this.#preCancelled.size > this.#maxTombstones) {
      const oldestKey = this.#preCancelled.keys().next().value;
      if (oldestKey === undefined) break;
      this.#preCancelled.delete(oldestKey);
    }
    return { cancelled: true, status: "recorded_prearrival_tombstone", reason: cleanReason };
  }

  snapshot() {
    const now = this.#nowFn();
    this.#pruneTombstones(now);
    return {
      inflightRequests: this.#inflight.size,
      pendingTombstones: this.#preCancelled.size,
      notificationsReceived: this.#notificationsReceived,
      cancelledCount: this.#cancelledCount,
      ignoredNonCancellable: this.#ignoredNonCancellable
    };
  }
}

