export function runMcpV14ContractAndCancellationLab(
  scenarioOrPayload = "structured-output-and-batch-cancel",
  options = {}
) {
  const t0 = performance.now();
  const scenarioObj =
    typeof scenarioOrPayload === "string"
      ? MCP_V14_CANCEL_SCENARIOS[scenarioOrPayload] ??
        MCP_V14_CANCEL_SCENARIOS["structured-output-and-batch-cancel"]
      : null;
  const rawPayload = scenarioObj ? scenarioObj.payload : scenarioOrPayload;
  const isBatch = Array.isArray(rawPayload);
  const items = isBatch ? rawPayload : [rawPayload];

  const maxTombstones = Math.max(1, Math.min(512, Math.trunc(Number(options.maxTombstones ?? 64))));
  const tombstoneTtlMs = Math.max(100, Math.trunc(Number(options.tombstoneTtlMs ?? 30000)));
  const injectOutputDrift = Boolean(options.injectOutputDrift);
  const acceptSse = Boolean(options.acceptSse);
  const agentId = Math.max(1, Math.min(255, Math.trunc(Number(options.agentId ?? 4))));
  const ex = options.wasmExports !== undefined ? options.wasmExports : cachedWasmExports;

  const rawTp = String(
    options.traceparent ?? "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01"
  ).trim();
  const inboundValid = STRICT_W3C_LOWER_RE.test(rawTp) && parseW3cTraceparent(rawTp) !== null;
  const effectiveParentTp = inboundValid
    ? rawTp
    : `00-${deterministicHex(`v14:${rawTp}`, 32)}-${deterministicHex(`v14:sp:${rawTp}`, 16)}-01`;
  const effectiveTraceId = effectiveParentTp.slice(3, 35);

  let virtualNowMs = 1_000_000;
  const registry = new RequestCancellationRegistry({
    maxTombstones,
    tombstoneTtlMs,
    nowFn: () => virtualNowMs
  });

  const preCancels = [
    ...(scenarioObj?.preCancel ?? []),
    ...(Array.isArray(options.preCancel) ? options.preCancel : [])
  ];
  for (const pc of preCancels) {
    registry.cancel(pc.requestId, pc.reason ?? "Pre-arrival cancellation");
    virtualNowMs += 5;
  }

  // Pass 1: Process notifications upfront in batch so sibling notifications/cancelled take immediate effect
  let notificationsElided = 0;
  for (const item of items) {
    if (isJsonRpcNotification(item)) {
      notificationsElided += 1;
      if (item.method === "notifications/cancelled") {
        const p = item.params && typeof item.params === "object" ? item.params : {};
        registry.cancel(p.requestId, p.reason ?? "Cancelled in batch");
      }
      virtualNowMs += 2;
    }
  }

  const responses = [];
  const otlpSpans = [];
  let cancelledElided = 0;
  let structuredOutputsValidated = 0;
  let inputSchemaRejections = 0;
  let outputSchemaBreaches = 0;
  let redactionsTotal = 0;
  let toolCallOrdinal = 0;

  for (let idx = 0; idx < items.length; idx += 1) {
    const item = items[idx];
    if (isJsonRpcNotification(item)) {
      continue;
    }
    if (
      !item ||
      typeof item !== "object" ||
      Array.isArray(item) ||
      item.jsonrpc !== "2.0" ||
      typeof item.method !== "string"
    ) {
      responses.push({
        jsonrpc: "2.0",
        id: item && typeof item === "object" && "id" in item ? item.id : null,
        error: { code: -32600, message: "Invalid JSON-RPC 2.0 Request" }
      });
      continue;
    }

    const reqId = item.id ?? null;
    const method = item.method;
    const params = item.params && typeof item.params === "object" ? item.params : {};
    const isInit = method === "initialize";
    const toolName = method === "tools/call" ? String(params.name ?? "unknown") : "";
    const spanLabel = method === "tools/call" ? `mcp.tools.call/${toolName}` : `mcp.${method}`;

    const child = deriveChildTraceparent(effectiveParentTp, {
      stepSeq: idx,
      agentId,
      label: spanLabel,
      wasmExports: ex
    });

    const token = registry.begin(reqId, { nonCancellable: isInit });
    try {
      if (token.isCancelled) {
        cancelledElided += 1;
        otlpSpans.push({
          batchIndex: idx,
          reqId,
          label: spanLabel,
          childSpanId: child.childSpanId,
          traceparent: child.traceparent,
          mcpCancelled: true,
          cancelReason: token.reason,
          status: "CANCELLED_ELIDED"
        });
        continue;
      }

      if (isInit) {
        const cap = negotiateMcpCapabilities(params.protocolVersion ?? "2025-11-25");
        responses.push({
          jsonrpc: "2.0",
          id: reqId,
          result: {
            protocolVersion: cap.negotiatedVersion,
            serverInfo: { name: "subvenyx-mcp-v14-gateway", version: "1.4.0" },
            capabilities: cap.capabilities
          }
        });
        otlpSpans.push({
          batchIndex: idx,
          reqId,
          label: spanLabel,
          childSpanId: child.childSpanId,
          traceparent: child.traceparent,
          mcpCancelled: false,
          status: "OK"
        });
      } else if (method === "tools/call") {
        toolCallOrdinal += 1;
        const contract = MCP_V14_TOOL_CONTRACTS[toolName];
        if (!contract) {
          responses.push({
            jsonrpc: "2.0",
            id: reqId,
            error: { code: -32601, message: `Unknown tool: ${toolName}` }
          });
          continue;
        }

        const rawArgs = params.arguments && typeof params.arguments === "object" ? params.arguments : {};
        const inViolations = JsonSchema2020Validator.validate(rawArgs, contract.inputSchema);
        if (inViolations.length > 0) {
          inputSchemaRejections += 1;
          responses.push({
            jsonrpc: "2.0",
            id: reqId,
            error: {
              code: -32602,
              message: "Invalid params: JSON-Schema Draft 2020-12 inputSchema violation",
              data: { tool: toolName, violations: inViolations }
            }
          });
          otlpSpans.push({
            batchIndex: idx,
            reqId,
            label: spanLabel,
            childSpanId: child.childSpanId,
            traceparent: child.traceparent,
            mcpCancelled: false,
            status: "ERR_-32602_INPUT_SCHEMA"
          });
          continue;
        }

        let structured;
        if (toolName === "moe_route_query") {
          const { cleanQuery, redactions } = redactQuery(rawArgs.prompt);
          redactionsTotal += redactions;
          const route = routeSparseTop2(
            cleanQuery,
            Number(rawArgs.vramGib ?? 6.0),
            Number(rawArgs.slaMs ?? 450)
          );
          structured = {
            primaryExpert: route.primaryExpert,
            secondaryExpert: route.secondaryExpert,
            redactions,
            childSpanId: child.childSpanId
          };
        } else {
          const topK = Number(rawArgs.topK ?? 2);
          const cit = inspectMcpCitationSpans(rawArgs.query, { topK });
          redactionsTotal += cit.redactions;
          structured = {
            hits: cit.hits.map((h) => ({
              id: h.id,
              rrf: Number(h.rrf.toFixed(6)),
              spans: h.citationSpans.length
            })),
            quantilesMsTuple: [0.126, 0.422, 0.681],
            redactions: cit.redactions,
            childSpanId: child.childSpanId
          };
        }

        const shouldDrift =
          injectOutputDrift ||
          (Boolean(scenarioObj?.forceOutputDriftOnSecondCall) && toolCallOrdinal >= 1 && reqId === "drifted-output-tuple");
        if (shouldDrift) {
          structured = {
            ...structured,
            quantilesMsTuple: [0.126, 0.422, 0.681, 9.999],
            undeclaredLeakField: "drift"
          };
        }

        const outViolations = JsonSchema2020Validator.validate(structured, contract.outputSchema);
        if (outViolations.length > 0) {
          outputSchemaBreaches += 1;
          responses.push({
            jsonrpc: "2.0",
            id: reqId,
            error: {
              code: -32603,
              message: "Internal error: Tool output violated JSON-Schema Draft 2020-12 outputSchema",
              data: { tool: toolName, violations: outViolations }
            }
          });
          otlpSpans.push({
            batchIndex: idx,
            reqId,
            label: spanLabel,
            childSpanId: child.childSpanId,
            traceparent: child.traceparent,
            mcpCancelled: false,
            status: "ERR_-32603_OUTPUT_SCHEMA"
          });
          continue;
        }

        structuredOutputsValidated += 1;
        responses.push({
          jsonrpc: "2.0",
          id: reqId,
          result: {
            content: [{ type: "text", text: JSON.stringify(structured) }],
            structuredContent: structured,
            isError: false
          }
        });
        otlpSpans.push({
          batchIndex: idx,
          reqId,
          label: spanLabel,
          childSpanId: child.childSpanId,
          traceparent: child.traceparent,
          mcpCancelled: false,
          status: "OK_STRUCTURED"
        });
      } else {
        responses.push({
          jsonrpc: "2.0",
          id: reqId,
          error: { code: -32601, message: `Method not found: ${method}` }
        });
      }
    } finally {
      registry.finish(reqId, token);
      virtualNowMs += 5;
    }
  }

  // Seal all active & cancelled spans into WASM CapabilityAuditRing with binary trace correlation
  let engine = "es2022-crc32c-mirror";
  let tracedAuditCorrelatedSlots = otlpSpans.length;
  const hasWasmV13 =
    ex &&
    typeof ex.par_audit_ring_record_traced === "function" &&
    typeof ex.par_audit_ring_count_trace === "function";

  if (hasWasmV13 && otlpSpans.length > 0) {
    engine = "wasm32-unknown-unknown";
    const enc = new TextEncoder();
    const ringPtr = ex.par_audit_ring_new();
    const rootPtr = ex.par_trace_context_new();
    const childPtr = ex.par_trace_context_new();
    const tpBytes = enc.encode(effectiveParentTp);
    const tpPtr = ex.par_wasm_alloc_bytes(tpBytes.length);
    try {
      new Uint8Array(ex.memory.buffer, tpPtr, tpBytes.length).set(tpBytes);
      ex.par_wasm_traceparent_parse(tpPtr, tpBytes.length, rootPtr);
      let tsNs = 20_000_000n;
      for (const sp of otlpSpans) {
        const auditNote = sp.mcpCancelled ? `cancel:${sp.label}` : `ok:${sp.label}`;
        const noteBytes = enc.encode(auditNote);
        const noteAlloc = Math.max(1, noteBytes.length);
        const notePtr = ex.par_wasm_alloc_bytes(noteAlloc);
        try {
          new Uint8Array(ex.memory.buffer, notePtr, noteBytes.length).set(noteBytes);
          ex.par_wasm_trace_derive_child(
            rootPtr,
            BigInt(sp.batchIndex),
            agentId >>> 0,
            notePtr,
            noteBytes.length,
            childPtr
          );
          ex.par_audit_ring_record_traced(
            ringPtr,
            tsNs,
            agentId >>> 0,
            sp.mcpCancelled ? 0x10 : 0x09,
            0x0f,
            childPtr,
            rootPtr + 16,
            notePtr,
            noteBytes.length
          );
        } finally {
          ex.par_wasm_free_bytes(notePtr, noteAlloc);
        }
        tsNs += 1_000_000n;
      }
      tracedAuditCorrelatedSlots = ex.par_audit_ring_count_trace(ringPtr, rootPtr);
    } finally {
      ex.par_wasm_free_bytes(tpPtr, tpBytes.length);
      ex.par_trace_context_free(childPtr);
      ex.par_trace_context_free(rootPtr);
      ex.par_audit_ring_free(ringPtr);
    }
  }

  const regSnap = registry.snapshot();
  const httpStatus = responses.length === 0 ? 202 : 200;
  const outBody = responses.length === 0 ? null : isBatch ? responses : responses[0];
  const sseWire =
    acceptSse && responses.length > 0
      ? responses.map((r) => `event: message
data: ${JSON.stringify(r)}

`).join("")
      : "";

  return {
    scenarioId: scenarioObj?.id ?? "custom",
    summary: scenarioObj?.summary ?? "Custom MCP v1.4 payload",
    httpStatus,
    contentType:
      httpStatus === 202
        ? "none (202 Accepted)"
        : acceptSse
        ? "text/event-stream; charset=utf-8"
        : "application/json",
    traceId: effectiveTraceId,
    effectiveParentTraceparent: effectiveParentTp,
    inboundCount: items.length,
    notificationsElided,
    cancelledElided,
    responseCount: responses.length,
    structuredOutputsValidated,
    inputSchemaRejections,
    outputSchemaBreaches,
    redactionsTotal,
    registrySnapshot: regSnap,
    otlpSpans,
    tracedAuditCorrelatedSlots,
    body: outBody,
    sseWire,
    engine,
    elapsedMs: Number((performance.now() - t0).toFixed(3))
  };
}


// ============================================================================
// v1.5 16-Byte C11/Rust/WASM/Python/Node CRC32C Cursor Codec,
// completion/complete, resources/subscribe, RFC 5424 Logging & ToolAnnotations
// ============================================================================

export class McpCursorCodec {
  static MAGIC = 0x5043;
  static VERSION = 1;
  static WIRE_BYTES = 16;
  static B64_LEN = 22;
  static MAX_OFFSET = 1_048_576;

  static SCOPE_TOOLS = 1;
  static SCOPE_RESOURCES = 2;
  static SCOPE_TEMPLATES = 3;
  static SCOPE_PROMPTS = 4;

  static ERR_B64 = -13;
  static ERR_MAGIC = -14;
  static ERR_SCOPE = -15;
  static ERR_SNAPSHOT = -16;
  static ERR_SEAL = -17;
  static ERR_BOUNDS = -18;

  static ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
  static #DECODE_LUT = (() => {
    const lut = new Int8Array(128).fill(-1);
    for (let i = 0; i < McpCursorCodec.ALPHABET.length; i += 1) {
      lut[McpCursorCodec.ALPHABET.charCodeAt(i)] = i;
    }
    return lut;
  })();

  static #crcBytes(bytes, wasmExports = null) {
    const ex = wasmExports ?? cachedWasmExports;
    if (
      ex &&
      typeof ex.par_wasm_crc32c === "function" &&
      typeof ex.par_wasm_alloc_bytes === "function" &&
      typeof ex.par_wasm_free_bytes === "function"
    ) {
      if (bytes.length === 0) {
        return 0;
      }
      const ptr = ex.par_wasm_alloc_bytes(bytes.length);
      try {
        new Uint8Array(ex.memory.buffer, ptr, bytes.length).set(bytes);
        return ex.par_wasm_crc32c(ptr, bytes.length) >>> 0;
      } finally {
        ex.par_wasm_free_bytes(ptr, bytes.length);
      }
    }
    return crc32cPortable(bytes) >>> 0;
  }

  static snapshotHash(keys, options = {}) {
    const joined = (keys ?? []).map((k) => String(k)).join("\n");
    return McpCursorCodec.#crcBytes(new TextEncoder().encode(joined), options.wasmExports ?? null);
  }

  static computeSeal(magic, version, scope, offset, snapshotCrc32c, options = {}) {
    const preimage = new Uint8Array(16);
    const dv = new DataView(preimage.buffer);
    dv.setUint16(0, magic & 0xffff, true);
    dv.setUint8(2, version & 0xff);
    dv.setUint8(3, scope & 0xff);
    dv.setUint32(4, offset >>> 0, true);
    dv.setUint32(8, snapshotCrc32c >>> 0, true);
    preimage[12] = 0x4d; // 'M'
    preimage[13] = 0x43; // 'C'
    preimage[14] = 0x50; // 'P'
    preimage[15] = 0x43; // 'C'
    return McpCursorCodec.#crcBytes(preimage, options.wasmExports ?? null);
  }

  static encodeBytesToB64Url(wire16) {
    const alph = McpCursorCodec.ALPHABET;
    let out = "";
    for (let g = 0; g < 5; g += 1) {
      const idx = g * 3;
      const triple = (wire16[idx] << 16) | (wire16[idx + 1] << 8) | wire16[idx + 2];
      out += alph[(triple >>> 18) & 0x3f];
      out += alph[(triple >>> 12) & 0x3f];
      out += alph[(triple >>> 6) & 0x3f];
      out += alph[triple & 0x3f];
    }
    out += alph[(wire16[15] >>> 2) & 0x3f];
    out += alph[(wire16[15] & 0x03) << 4];
    return out;
  }

  static encode(scope, offset, snapshotCrc32c, options = {}) {
    if (
      typeof scope !== "number" ||
      !Number.isInteger(scope) ||
      scope < McpCursorCodec.SCOPE_TOOLS ||
      scope > McpCursorCodec.SCOPE_PROMPTS
    ) {
      throw new RangeError(`Invalid cursor scope: ${String(scope)}`);
    }
    if (
      typeof offset !== "number" ||
      !Number.isInteger(offset) ||
      offset <= 0 ||
      offset > McpCursorCodec.MAX_OFFSET
    ) {
      throw new RangeError(`Invalid cursor offset: ${String(offset)}`);
    }
    const snap = snapshotCrc32c >>> 0;
    const seal = McpCursorCodec.computeSeal(McpCursorCodec.MAGIC, McpCursorCodec.VERSION, scope, offset, snap, options);
    const wire = new Uint8Array(16);
    const dv = new DataView(wire.buffer);
    dv.setUint16(0, McpCursorCodec.MAGIC, true);
    dv.setUint8(2, McpCursorCodec.VERSION);
    dv.setUint8(3, scope);
    dv.setUint32(4, offset >>> 0, true);
    dv.setUint32(8, snap, true);
    dv.setUint32(12, seal, true);
    return McpCursorCodec.encodeBytesToB64Url(wire);
  }

  static decodeWireBytes(cursor) {
    if (typeof cursor !== "string" || cursor.length !== McpCursorCodec.B64_LEN) {
      return { ok: false, code: McpCursorCodec.ERR_B64, wire: null, message: "Must be 22-char unpadded base64url" };
    }
    const sextets = new Uint8Array(22);
    for (let i = 0; i < 22; i += 1) {
      const ch = cursor.charCodeAt(i);
      const s = ch < 128 ? McpCursorCodec.#DECODE_LUT[ch] : -1;
      if (s < 0) {
        return { ok: false, code: McpCursorCodec.ERR_B64, wire: null, message: "Illegal base64url character" };
      }
      sextets[i] = s;
    }
    if ((sextets[21] & 0x0f) !== 0) {
      return { ok: false, code: McpCursorCodec.ERR_B64, wire: null, message: "Non-canonical trailing base64url bits" };
    }
    const wire = new Uint8Array(16);
    for (let g = 0; g < 5; g += 1) {
      const sIdx = g * 4;
      const wIdx = g * 3;
      const quad = (sextets[sIdx] << 18) | (sextets[sIdx + 1] << 12) | (sextets[sIdx + 2] << 6) | sextets[sIdx + 3];
      wire[wIdx] = (quad >>> 16) & 0xff;
      wire[wIdx + 1] = (quad >>> 8) & 0xff;
      wire[wIdx + 2] = quad & 0xff;
    }
    wire[15] = ((sextets[20] << 2) | (sextets[21] >>> 4)) & 0xff;
    return { ok: true, code: 0, wire, message: "ok" };
  }

  static decodeAndVerify(cursor, expectedScope, expectedSnapshotCrc32c, totalItems, options = {}) {
    const decoded = McpCursorCodec.decodeWireBytes(cursor);
    if (!decoded.ok || !decoded.wire) {
      return { code: decoded.code, offset: 0, message: decoded.message };
    }
    const dv = new DataView(decoded.wire.buffer);
    const magic = dv.getUint16(0, true);
    const version = dv.getUint8(2);
    const scope = dv.getUint8(3);
    const offset = dv.getUint32(4, true);
    const snapCrc = dv.getUint32(8, true);
    const sealCrc = dv.getUint32(12, true);

    const computedSeal = McpCursorCodec.computeSeal(magic, version, scope, offset, snapCrc, options);
    if (sealCrc !== computedSeal) {
      return { code: McpCursorCodec.ERR_SEAL, offset: 0, message: "CRC32C integrity seal mismatch (-17)" };
    }
    if (magic !== McpCursorCodec.MAGIC || version !== McpCursorCodec.VERSION) {
      return { code: McpCursorCodec.ERR_MAGIC, offset: 0, message: "Unsupported cursor header or version (-14)" };
    }
    if (
      typeof expectedScope !== "number" ||
      !Number.isInteger(expectedScope) ||
      scope < McpCursorCodec.SCOPE_TOOLS ||
      scope > McpCursorCodec.SCOPE_PROMPTS ||
      expectedScope < McpCursorCodec.SCOPE_TOOLS ||
      expectedScope > McpCursorCodec.SCOPE_PROMPTS ||
      scope !== expectedScope
    ) {
      return { code: McpCursorCodec.ERR_SCOPE, offset: 0, message: "Cursor scope does not match target endpoint (-15)" };
    }
    if (snapCrc !== (expectedSnapshotCrc32c >>> 0)) {
      return { code: McpCursorCodec.ERR_SNAPSHOT, offset: 0, message: "Collection snapshot epoch changed (-16)" };
    }
    const maxTotal = Math.max(0, Math.trunc(Number(totalItems) || 0));
    if (offset <= 0 || offset > McpCursorCodec.MAX_OFFSET || offset >= maxTotal) {
      return { code: McpCursorCodec.ERR_BOUNDS, offset: 0, message: "Pagination offset out of bounds (-18)" };
    }
    return { code: 0, offset, message: "ok" };
  }
}

export const RFC5424_LOG_LEVELS = Object.freeze([
  "debug",
  "info",
  "notice",
  "warning",
  "error",
  "critical",
  "alert",
  "emergency"
]);

